test('rooms: check in, or the room is released for others', async () => {
  const a = client(), b = client();
  for (const [local, name] of [['rcia', 'Cia Ann'], ['rcib', 'Cib Ben']]) assert.equal((await owner('POST', '/api/users', { local, domain: 'acme.com', name, password: 'password123' })).status, 201);
  await login(a, 'rcia@acme.com'); await login(b, 'rcib@acme.com');
  const mk = async (name, check_in) => (await owner('POST', '/api/rooms', { name, check_in })).body;
  const ra = await mk('Zz CI A', true), rb = await mk('Zz CI B', true), rc = await mk('Zz CI C', false);
  assert.equal(ra.check_in, true);
  const t = Date.now();
  await a('POST', '/api/events', { title: 'No show', start: t - 15 * 6e4, end: t + 45 * 6e4, rooms: [ra.id] });
  await owner('POST', '/api/events', { title: 'Here', start: t - 5 * 6e4, end: t + 55 * 6e4, rooms: [rb.id], guests: ['rcia@acme.com'] });
  await a('POST', '/api/events', { title: 'No check-in needed', start: t - 15 * 6e4, end: t + 45 * 6e4, rooms: [rc.id] });
  const now = async (c, id) => (await c('GET', '/api/rooms/now')).body.find((x) => x.id === id);
  assert.equal((await now(a, rb.id)).busy.release_at, t - 5 * 6e4 + 10 * 6e4, 'released unless someone checks in by then');
  assert.equal((await b('POST', `/api/rooms/${rb.id}/check-in`)).status, 409, 'not in that meeting');
  assert.equal((await a('POST', `/api/rooms/${rb.id}/check-in`)).status, 200, 'a guest checks in');
  assert.deepEqual([(await now(a, rb.id)).busy.checked_in, (await now(a, rb.id)).busy.release_at], [true, null]);
  assert.equal((await now(a, rc.id)).busy.release_at, null, 'no check-in for this room');

  const { releaseNoShows, askCheckIns } = await import('../src/routes/rooms.js');
  // At the start, those in the meeting are asked to check in (once); not when someone already has.
  const titles = async (c) => { const x = (await c('GET', '/api/notifications')).body; return (Array.isArray(x) ? x : x.items).map((n) => n.title); };
  assert.equal(askCheckIns(Date.now()), 0, 'the no-show started 15 minutes ago: past asking; B is checked in; C has no check-in');
  const busyC = (await a('GET', `/api/events?from=${t - 36e5}&to=${t + 36e5}`)).body.find((e) => e.title === 'No check-in needed');
  await a('DELETE', `/api/events/${busyC.id}`);
  await owner('PATCH', `/api/rooms/${rc.id}`, { check_in: true });
  const starting = (await a('POST', '/api/events', { title: 'Starting now', start: Date.now() - 6e4, end: Date.now() + 30 * 6e4, rooms: [rc.id] })).body;
  assert.equal(starting.rooms[0].status, 'yes');
  assert.equal(askCheckIns(Date.now()), 1);
  assert.equal(askCheckIns(Date.now()), 0, 'once');
  const bellA = (await a('GET', '/api/notifications')).body;
  assert.equal((Array.isArray(bellA) ? bellA : bellA.items).find((x) => x.title === 'Check in to Zz CI C').link, '/calendar?rooms=now', 'opens Rooms now');
  assert.ok(!(await titles(b)).includes('Check in to Zz CI C'), 'only those in the meeting');
  await a('POST', `/api/rooms/${rc.id}/check-in`);
  assert.equal(releaseNoShows(Date.now()), 1, 'only the no-show');
  assert.equal(releaseNoShows(Date.now()), 0, 'once');
  assert.equal(releaseNoShows(Date.now() + 10 * 6e4), 0, 'checked in: kept');
  assert.equal((await now(b, ra.id)).busy, null, 'free again');
  assert.equal((await now(b, rc.id)).busy.title, 'Starting now', 'checked in: kept');
  const bell = (await a('GET', '/api/notifications')).body;
  assert.ok((Array.isArray(bell) ? bell : bell.items || bell.notifications).some((n) => n.title === 'Zz CI A was released'));
  assert.equal((await b('POST', `/api/rooms/${ra.id}/book-now`, { minutes: 15 })).status, 201, 'someone else can have it');
  const usage = (await owner('GET', '/api/rooms/usage?days=7')).body.rooms;
  assert.deepEqual([usage.find((x) => x.id === ra.id).no_shows, usage.find((x) => x.id === rb.id).no_shows], [1, 0], 'the usage report counts no-shows');
  for (const r of [ra, rb, rc]) await owner('DELETE', `/api/rooms/${r.id}`);
});

test('rooms: some only admins can book', async () => {
  const a = client();
  assert.equal((await owner('POST', '/api/users', { local: 'radm', domain: 'acme.com', name: 'Ray Adm', password: 'password123' })).status, 201);
  await login(a, 'radm@acme.com');
  const room = (await owner('POST', '/api/rooms', { name: 'Zz Exec room', admins_only: true })).body;
  assert.equal(room.admins_only, true);
  const t = Date.now() + 2 * 864e5;
  assert.equal((await a('GET', '/api/rooms')).body.find((r) => r.id === room.id).can_book, false);
  assert.equal((await owner('GET', '/api/rooms')).body.find((r) => r.id === room.id).can_book, true);
  const mine = (await a('POST', '/api/events', { title: 'Mine', start: t, end: t + 36e5, rooms: [room.id] })).body;
  assert.deepEqual(mine.rooms.map((r) => [r.status, r.admins_only]), [['no', true]], 'declined: admins only');
  const boss = (await owner('POST', '/api/events', { title: 'Board', start: t + 2 * 36e5, end: t + 3 * 36e5, rooms: [room.id] })).body;
  assert.equal(boss.rooms[0].status, 'yes');
  assert.equal((await a('POST', `/api/rooms/${room.id}/book-now`, {})).status, 403);
  assert.equal((await a('PATCH', `/api/rooms/${room.id}`, { admins_only: false })).status, 403, 'only admins change rooms');
  assert.equal((await owner('PATCH', `/api/rooms/${room.id}`, { capacity: 6 })).body.admins_only, true, 'kept');
  assert.equal((await owner('PATCH', `/api/rooms/${room.id}`, { admins_only: false })).body.admins_only, false);
  assert.equal((await a('PATCH', `/api/events/${mine.id}`, { rooms: [room.id] })).body.rooms[0].status, 'yes', 'open to everyone now');
  await owner('DELETE', `/api/rooms/${room.id}`);
});

test('rooms: import from a CSV file and export again', async () => {
  const { roomsFromCsv } = await import('../src/routes/rooms.js');
  assert.deepEqual(roomsFromCsv('Seats\n4').problems, ['The first row needs a Name column']);
  const parsed = roomsFromCsv('Room name,Capacity,Location,Equipment\nZz Csv Atrium,40,Ground floor,"Video, Screen; video"\n,3,,\nZz Csv Pod,two,,\n\nZz Csv Booth,,,\n');
  assert.deepEqual(parsed.rooms, [{ name: 'Zz Csv Atrium', capacity: 40, location: 'Ground floor', features: ['Video', 'Screen'] }, { name: 'Zz Csv Booth', capacity: null, location: null, features: [] }]);
  assert.deepEqual(parsed.problems, ['Line 3: no name', 'Line 4: seats should be a number of people']);
  const a = client();
  assert.equal((await owner('POST', '/api/users', { local: 'rcsv', domain: 'acme.com', name: 'Ros Csv', password: 'password123' })).status, 201);
  await login(a, 'rcsv@acme.com');
  const csv = Buffer.from('Name,Seats,Where,Equipment\nZz Csv Atrium,40,Ground floor,"Video, Whiteboard"\nZz Csv Booth,1,,\n');
  assert.equal((await a('POST', '/api/rooms/import', csv, { raw: true })).status, 403, 'admins only');
  const first = (await owner('POST', '/api/rooms/import', csv, { raw: true })).body;
  assert.deepEqual([first.added, first.updated], [2, 0]);
  const again = (await owner('POST', '/api/rooms/import', Buffer.from('name,seats\nzz csv atrium,50\n'), { raw: true })).body;
  assert.deepEqual([again.added, again.updated], [0, 1], 'same name (ignoring case): updated');
  const atrium = (await owner('GET', '/api/rooms')).body.find((r) => r.name === 'zz csv atrium');
  assert.deepEqual([atrium.capacity, atrium.location, atrium.features], [50, 'Ground floor', ['Video', 'Whiteboard']], 'columns the file hasn’t: kept');
  const out = (await owner('GET', '/api/rooms/export.csv')).body;
  assert.match(out, /^Name,Seats,Where,Equipment,Admins only,Check-in\r\n/);
  assert.match(out, /Zz Csv Booth,1,,,no,no\r\n/);
  // Admins only and Check-in, yes or no.
  const flags = (await owner('POST', '/api/rooms/import', Buffer.from('Name,Admins only,Check-in\nZz Csv Booth,yes,Y\nZz Csv Atrium,maybe,no\n'), { raw: true })).body;
  assert.deepEqual([flags.updated, flags.problems], [1, ['Line 3: Admins only should be yes or no']]);
  const booth = (await owner('GET', '/api/rooms')).body.find((r) => r.name === 'Zz Csv Booth');
  assert.deepEqual([booth.admins_only, booth.check_in, booth.capacity], [true, true, 1]);
  assert.equal((await owner('POST', '/api/rooms/import', Buffer.from('nothing here'), { raw: true })).status, 400);
  for (const r of (await owner('GET', '/api/rooms')).body.filter((x) => /^zz csv/i.test(x.name))) await owner('DELETE', `/api/rooms/${r.id}`);
});

