test('announcements: an admin posts one; everyone sees it until they dismiss it or it ends', async () => {
  const a = client();
  assert.equal((await owner('POST', '/api/users', { local: 'annc', domain: 'acme.com', name: 'Ann Nounce', password: 'password123' })).status, 201);
  await login(a, 'annc@acme.com');
  assert.equal((await a('POST', '/api/announcements', { text: 'Not allowed' })).status, 403, 'admins only');
  assert.equal((await owner('POST', '/api/announcements', { text: 'x', link: 'javascript:alert(1)' })).status, 400);
  const ann = (await owner('POST', '/api/announcements', { text: 'Office closed Friday', link: '/calendar', tone: 'warn' })).body;
  const old = (await owner('POST', '/api/announcements', { text: 'Ends soon', until: Date.now() + 300 })).body;
  let mine = (await a('GET', '/api/announcements')).body;
  assert.deepEqual(mine.map((x) => x.text), ['Ends soon', 'Office closed Friday']);
  assert.equal(mine.find((x) => x.id === ann.id).tone, 'warn');
  await new Promise((r) => setTimeout(r, 350));
  assert.deepEqual((await a('GET', '/api/announcements')).body.map((x) => x.text), ['Office closed Friday'], 'ended ones go');
  await a('POST', `/api/announcements/${ann.id}/dismiss`);
  assert.deepEqual((await a('GET', '/api/announcements')).body, [], 'dismissed');
  assert.equal((await owner('GET', '/api/announcements/all')).body.find((x) => x.id === ann.id).dismissed, 1);
  assert.equal((await owner('DELETE', `/api/announcements/${ann.id}`)).status, 200);
  assert.ok(!(await owner('GET', '/api/announcements/all')).body.some((x) => x.id === ann.id));
  void old;
});

test('announcements: for one group only, and starting later', async () => {
  const a = client(); const b = client();
  for (const local of ['anng1', 'anng2']) assert.equal((await owner('POST', '/api/users', { local, domain: 'acme.com', name: local, password: 'password123' })).status, 201);
  const aid = (await login(a, 'anng1@acme.com')).id;
  await login(b, 'anng2@acme.com');
  const g = (await owner('POST', '/api/groups', { name: 'Night shift' })).body;
  await owner('PUT', `/api/groups/${g.id}/members`, { user_ids: [aid] });
  assert.equal((await owner('POST', '/api/announcements', { text: 'x', group_id: 'nope' })).status, 400, 'a group of this company');
  const forGroup = (await owner('POST', '/api/announcements', { text: 'Night shift: new rota', group_id: g.id })).body;
  assert.ok((await a('GET', '/api/announcements')).body.some((x) => x.id === forGroup.id), 'members see it');
  assert.ok(!(await b('GET', '/api/announcements')).body.some((x) => x.id === forGroup.id), 'others don\'t');
  const row = (await owner('GET', '/api/announcements/all')).body.find((x) => x.id === forGroup.id);
  assert.equal(row.group_name, 'Night shift');
  assert.equal(row.group_size, 1);
  // Starting later: nobody sees it until then; the admin list has it, with when.
  assert.equal((await owner('POST', '/api/announcements', { text: 'x', starts_at: Date.now() + 864e5, until: Date.now() + 3600e3 })).status, 400, 'ends after it starts');
  const later = (await owner('POST', '/api/announcements', { text: 'Maintenance tonight', starts_at: Date.now() + 400 })).body;
  assert.ok(later.starts_at > Date.now());
  assert.ok(!(await b('GET', '/api/announcements')).body.some((x) => x.id === later.id), 'not yet');
  assert.ok((await owner('GET', '/api/announcements/all')).body.some((x) => x.id === later.id && x.starts_at), 'admins see what\'s coming');
  const past = (await owner('POST', '/api/announcements', { text: 'Already', starts_at: Date.now() - 1000 })).body;
  assert.equal(past.starts_at, null, 'a start in the past is straight away');
  await new Promise((r) => setTimeout(r, 450));
  const { announceStarted } = await import('../src/routes/announcements.js');
  assert.ok(announceStarted() >= 1, 'open tabs are told when it starts');
  assert.equal(announceStarted(), 0, 'only once');
  assert.ok((await b('GET', '/api/announcements')).body.some((x) => x.id === later.id), 'started');
  // By email too: needs this server's email (off in these tests); the message itself.
  assert.equal((await owner('POST', '/api/announcements', { text: 'x', email: true })).status, 400, 'no email here');
  const { announcementMail, audienceOf } = await import('../src/routes/announcements.js');
  assert.deepEqual(audienceOf({ org_id: forGroup.org_id, group_id: g.id }), ['anng1@acme.com']);
  assert.ok(audienceOf({ org_id: forGroup.org_id, group_id: null }).includes('anng2@acme.com'));
  const m = announcementMail({ text: 'Office closed Friday', link: '/calendar', tone: 'warn', base: 'https://ws.example.com/' }, { author: 'Olivia Owner', org: 'Acme' });
  assert.equal(m.subject, 'Important: Office closed Friday');
  assert.equal(m.text, 'Office closed Friday\n\nhttps://ws.example.com/calendar\n\n— Olivia Owner, to everyone at Acme. It\'s also shown at the top of Workspace.');
  assert.match(announcementMail({ text: 'y'.repeat(100), tone: 'info' }, { group: 'Night shift' }).subject, /^Announcement: y{67}…$/);
  assert.match(announcementMail({ text: 'z', link: 'https://x.test/a' }, { group: 'Night shift' }).text, /https:\/\/x\.test\/a[\s\S]*to the Night shift group/);
  for (const x of [forGroup, later, past]) await owner('DELETE', `/api/announcements/${x.id}`);
});

test('forms: questions are tidied and answers checked', async () => {
  const { cleanQuestions, checkAnswers, responseTable } = await import('../src/routes/forms.js');
  const qs = cleanQuestions([
    { id: 'name', type: 'short', title: 'Your name', required: true },
    { id: 'lunch', type: 'choice', title: 'Lunch', options: ['Fish', ' Veg ', 'Veg', ''] },
    { id: 'days', type: 'checkbox', title: 'Days', options: ['Mon', 'Tue', 'Wed'] },
    { id: 'rate', type: 'scale', title: 'Rate', max: 7 },
    { id: 'when', type: 'date', title: 'When' },
    { type: 'nonsense', title: 'x', options: ['a'] },
  ]);
  assert.deepEqual(qs[1].options, ['Fish', 'Veg'], 'trimmed, no blanks or repeats');
  assert.equal(qs[3].max, 5, 'scales go to 5 or 10');
  assert.equal(qs[5].type, 'short');
  assert.equal(qs[5].options, undefined, 'only choice questions have options');
  assert.throws(() => checkAnswers(qs, {}), /Your name: this question needs an answer/);
  assert.throws(() => checkAnswers(qs, { name: 'A', lunch: 'Meat' }), /choose from the options/);
  assert.throws(() => checkAnswers(qs, { name: 'A', rate: 6 }), /1 to 5/);
  assert.throws(() => checkAnswers(qs, { name: 'A', when: 'tomorrow' }), /enter a date/);
  const a = checkAnswers(qs, { name: '  Ann ', lunch: 'Veg', days: ['Wed', 'Mon', 'Mon'], rate: '4', extra: 'ignored', when: '' });
  assert.deepEqual(a, { name: 'Ann', lunch: 'Veg', days: ['Mon', 'Wed'], rate: 4 });
  const table = responseTable({ questions: qs, audience: 'public' }, [{ created_at: 0, answers: a }]);
  assert.deepEqual(table[0].slice(0, 3), ['Submitted', 'Your name', 'Lunch']);
  assert.equal(table[1][3], 'Mon; Wed');
});

