test('forms: people can change their response afterwards when the form allows it', async () => {
  const made = (await owner('POST', '/api/forms', { title: 'Lunch order' })).body;
  const f = (await owner('PUT', `/api/forms/${made.id}`, { audience: 'public', quiz: true, show_score: true, questions: [
    { id: 'food', type: 'choice', title: 'Food', options: ['Pizza', 'Salad'], required: true, answer: 'Salad', points: 1 },
    { id: 'n', type: 'short', title: 'How many', check: { kind: 'number', op: 'between', a: 1, b: 5 } },
  ] })).body;
  const anon = client();
  const first = (await anon('POST', `/api/public/forms/${f.token}`, { answers: { food: 'Pizza', n: '2' } })).body;
  assert.equal(first.edit_key, undefined, 'not unless the form allows it');
  await owner('PUT', `/api/forms/${f.id}`, { allow_edit: true });
  const sent = (await anon('POST', `/api/public/forms/${f.token}`, { answers: { food: 'Pizza', n: '2' } })).body;
  assert.ok(sent.edit_key);
  assert.equal(sent.score, 0);
  const key = sent.edit_key;
  assert.deepEqual((await anon('GET', `/api/public/forms/${f.token}/response/${key}`)).body.answers, { food: 'Pizza', n: '2' });
  assert.equal((await anon('GET', `/api/public/forms/${f.token}/response/nope`)).status, 404);
  assert.equal((await anon('PUT', `/api/public/forms/${f.token}/response/${key}`, { answers: { food: 'Salad', n: '9' } })).status, 400, 'checked like a new one');
  const changed = await anon('PUT', `/api/public/forms/${f.token}/response/${key}`, { answers: { food: 'Salad', n: '3' } });
  assert.equal(changed.status, 200);
  assert.equal(changed.body.score, 1);
  const list = (await owner('GET', `/api/forms/${f.id}/responses`)).body.responses;
  assert.equal(list.length, 2, 'changed, not added');
  const mine = list.find((r) => r.answers.food === 'Salad');
  assert.equal(mine.answers.n, '3');
  assert.ok(mine.updated_at);
  // Once the form stops taking responses, it can't be changed either.
  await owner('PUT', `/api/forms/${f.id}`, { accepting: false });
  assert.equal((await anon('PUT', `/api/public/forms/${f.token}/response/${key}`, { answers: { food: 'Pizza' } })).status, 409);
  await owner('PUT', `/api/forms/${f.id}`, { accepting: true, allow_edit: false });
  assert.equal((await anon('GET', `/api/public/forms/${f.token}/response/${key}`)).status, 404, 'turning it off stops the links');
});

test('chat: "Seen" in direct messages, unless either person turns read receipts off', async () => {
  const mk = async (local, name) => { const c = client(); const r = await owner('POST', '/api/users', { local, domain: 'acme.com', name, password: 'password123' }); await login(c, `${local}@acme.com`); return [c, r.body.id]; };
  const [rae, raeId] = await mk('seena', 'Rae Seen');
  const [tom, tomId] = await mk('seenb', 'Tom Seen');
  const dm = (await rae('POST', '/api/chat/dm', { user_id: tomId })).body.id;
  await rae('POST', `/api/chat/channels/${dm}/messages`, { body: 'Lunch?' });
  const before = (await rae('GET', `/api/chat/channels/${dm}/seen`)).body.read_at;
  await tom('POST', `/api/chat/channels/${dm}/read`);
  const seen = (await rae('GET', `/api/chat/channels/${dm}/seen`)).body.read_at;
  assert.ok(seen && (!before || seen > before), 'Tom has read it');
  // Not for channels.
  const general = (await rae('GET', '/api/chat/channels')).body.channels?.find((c) => !c.dm_key) || (await rae('GET', '/api/chat/channels')).body.find?.((c) => !c.dm_key);
  if (general) assert.equal((await rae('GET', `/api/chat/channels/${general.id}/seen`)).body.read_at, null);
  // Off for one means off for both.
  assert.equal((await tom('PUT', '/api/chat/me/read-receipts', { on: false })).body.on, false);
  assert.equal((await rae('GET', `/api/chat/channels/${dm}/seen`)).body.read_at, null);
  assert.equal((await tom('GET', `/api/chat/channels/${dm}/seen`)).body.read_at, null);
  assert.equal((await tom('PUT', '/api/chat/me/read-receipts', { on: true })).body.on, true);
  assert.ok((await rae('GET', `/api/chat/channels/${dm}/seen`)).body.read_at);
  assert.ok(raeId);
});

test('notes: pictures on a note, seen by everyone it is shared with', async () => {
  const png = Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==', 'base64');
  const pia = client();
  const made = await owner('POST', '/api/users', { local: 'notepic', domain: 'acme.com', name: 'Pia Picture', password: 'password123' });
  await login(pia, 'notepic@acme.com');
  const n = (await owner('POST', '/api/notes', { title: 'Whiteboard' })).body;
  const up = (body, type) => owner('POST', `/api/notes/${n.id}/pictures`, body, { raw: true, headers: { 'content-type': type } });
  assert.equal((await up('<svg/>', 'image/svg+xml')).status, 400, 'no SVG');
  const added = await up(png, 'image/png');
  assert.equal(added.status, 201);
  assert.equal(added.body.pictures.length, 1);
  const pid = added.body.pictures[0];
  const { orgStorageUsed } = await import('../src/tenancy.js');
  const me = (await owner('GET', '/api/auth/me')).body.user;
  const used = orgStorageUsed(me.org_id);
  assert.ok(used >= png.length, 'counted in the company\'s storage');
  assert.equal((await pia('GET', `/api/notes/${n.id}/pictures/${pid}`, undefined, { binary: true })).status, 404, 'not shared yet');
  await owner('PUT', `/api/notes/${n.id}/shares`, { user_ids: [made.body.id] });
  const got = await pia('GET', `/api/notes/${n.id}/pictures/${pid}`, undefined, { binary: true });
  assert.equal(got.status, 200);
  assert.equal(got.headers.get('content-type'), 'image/png');
  assert.deepEqual(got.body, png);
  // A copy gets its own picture; taking it off one leaves the other.
  const copy = (await pia('POST', `/api/notes/${n.id}/copy`)).body;
  assert.equal(copy.pictures.length, 1);
  assert.notEqual(copy.pictures[0], pid);
  assert.equal((await pia('DELETE', `/api/notes/${n.id}/pictures/${pid}`)).body.pictures.length, 0);
  assert.equal((await pia('GET', `/api/notes/${copy.id}/pictures/${copy.pictures[0]}`, undefined, { binary: true })).status, 200);
});

test('drive: duplicate files are found by content, whatever they are called', async () => {
  const dup = client();
  await owner('POST', '/api/users', { local: 'dupes', domain: 'acme.com', name: 'Dee Dupes', password: 'password123' });
  await login(dup, 'dupes@acme.com');
  const up = (name, body, parent = '') => dup('POST', `/api/files/upload?name=${encodeURIComponent(name)}${parent ? `&parent=${parent}` : ''}`, body, { raw: true });
  const folder = (await dup('POST', '/api/files/folder', { name: 'Old' })).body;
  const a = (await up('report.pdf', 'PDF-CONTENT-1234')).body;
  const b = (await up('report (1).pdf', 'PDF-CONTENT-1234', folder.id)).body;
  const c = (await up('copy of report.pdf', 'PDF-CONTENT-1234')).body;
  await up('other.pdf', 'PDF-CONTENT-9999'); // same size, other content
  await up('small.txt', 'x');
  const r = (await dup('GET', '/api/files/duplicates')).body;
  assert.equal(r.groups.length, 1);
  assert.equal(r.incomplete, false);
  const g = r.groups[0];
  assert.deepEqual(g.files.map((f) => f.id).sort(), [a.id, b.id, c.id].sort());
  assert.equal(g.wasted, 2 * 16);
  assert.equal(g.files.find((f) => f.id === b.id).folder.name, 'Old');
  // Trashed copies don't count; others' files never show.
  await dup('PATCH', `/api/files/${c.id}`, { trashed: true });
  assert.equal((await dup('GET', '/api/files/duplicates')).body.groups[0].files.length, 2);
  assert.equal((await owner('GET', '/api/files/duplicates')).body.groups.some((x) => x.files.some((f) => f.id === a.id)), false);
});

