test('task attachments: files from Drive, shared with the people on the list', async () => {
  const kay = client(); await login(kay, 'kay@keepco.com');
  const tb = await kay('POST', '/api/users', { local: 'tfb', domain: 'keepco.com', name: 'Tess Files', password: 'password123' });
  const tc = await kay('POST', '/api/users', { local: 'tfc', domain: 'keepco.com', name: 'Theo Later', password: 'password123' });
  const tess = client(); await login(tess, 'tfb@keepco.com');
  const theo = client(); await login(theo, 'tfc@keepco.com');
  const list = (await kay('POST', '/api/tasks/lists', { name: 'Fit-out' })).body.id;
  await kay('PUT', `/api/tasks/lists/${list}/members`, { user_ids: [tb.body.id] });
  const task = (await kay('POST', `/api/tasks/lists/${list}/tasks`, { title: 'Order chairs', repeat: 'monthly', due: '2026-12-01' })).body;
  const folder = (await kay('POST', '/api/tasks/files-folder')).body.id;
  assert.equal((await kay('POST', '/api/tasks/files-folder')).body.id, folder, 'the same folder each time');
  const quote = (await kay('POST', `/api/files/upload?parent=${folder}&name=quote.pdf`, '%PDF-1.4 quote', { raw: true })).body;
  const theirs = (await theo('POST', '/api/files/upload?name=private.txt', 'mine', { raw: true })).body;
  assert.equal((await kay('POST', `/api/tasks/tasks/${task.id}/attachments`, { file_id: theirs.id })).status, 400, 'not one you can open');
  assert.equal((await tess('GET', `/api/files/${quote.id}`)).status, 404);
  const r = await kay('POST', `/api/tasks/tasks/${task.id}/attachments`, { file_id: quote.id });
  assert.equal(r.status, 201);
  assert.deepEqual(r.body.attachments.map((a) => [a.name, a.can_open]), [['quote.pdf', true]]);
  assert.equal((await kay('POST', `/api/tasks/tasks/${task.id}/attachments`, { file_id: quote.id })).body.attachments.length, 1, 'once');
  assert.equal((await tess('GET', `/api/files/${quote.id}`)).status, 200, 'people on the list can view it');
  assert.equal((await tess('GET', `/api/tasks/lists/${list}/tasks`)).body[0].attachments[0].can_open, true);
  // Someone added to the list later gets it too.
  await kay('PUT', `/api/tasks/lists/${list}/members`, { user_ids: [tb.body.id, tc.body.id] });
  assert.equal((await theo('GET', `/api/files/${quote.id}`)).status, 200);
  // The next one of a repeating task keeps its files.
  await kay('PATCH', `/api/tasks/tasks/${task.id}`, { done: true, today: '2026-12-01' });
  const open = (await kay('GET', `/api/tasks/lists/${list}/tasks`)).body.find((t) => !t.done);
  assert.deepEqual(open.attachments.map((a) => a.name), ['quote.pdf']);
  // Taking it off leaves the access people were given.
  const off = await tess('DELETE', `/api/tasks/tasks/${open.id}/attachments/${quote.id}`);
  assert.deepEqual(off.body.attachments, []);
  assert.equal((await tess('GET', `/api/files/${quote.id}`)).status, 200);
  assert.equal((await theo('POST', `/api/tasks/tasks/${task.id}/attachments`, { file_id: quote.id })).status, 201, 'anyone on the list can attach');
});

test('tasks waiting on others: same list, no loops, and a note when it can start', async () => {
  const kay = client(); await login(kay, 'kay@keepco.com');
  const wb = await kay('POST', '/api/users', { local: 'twb', domain: 'keepco.com', name: 'Wes Waiting', password: 'password123' });
  const wes = client(); await login(wes, 'twb@keepco.com');
  const list = (await kay('POST', '/api/tasks/lists', { name: 'Launch plan' })).body.id;
  const other = (await kay('POST', '/api/tasks/lists', { name: 'Elsewhere' })).body.id;
  await kay('PUT', `/api/tasks/lists/${list}/members`, { user_ids: [wb.body.id] });
  const add = async (title, extra = {}) => (await kay('POST', `/api/tasks/lists/${list}/tasks`, { title, ...extra })).body;
  const design = await add('Design'), copy = await add('Write copy'), print = await add('Print flyers', { assignee_id: wb.body.id });
  const away = (await kay('POST', `/api/tasks/lists/${other}/tasks`, { title: 'Away' })).body;
  const wait = (t, ids) => kay('PUT', `/api/tasks/tasks/${t.id}/waiting-on`, { task_ids: ids });
  assert.equal((await wait(print, [away.id])).status, 400, 'only on its own list');
  assert.equal((await wait(print, [print.id])).status, 400, 'not on itself');
  const r = await wait(print, [design.id, copy.id]);
  assert.deepEqual(r.body.blocked_by.sort(), [design.id, copy.id].sort());
  assert.equal((await wait(design, [print.id])).status, 400, 'no loops');
  await wait(copy, [design.id]);
  assert.equal((await wait(design, [copy.id])).status, 400, 'no loops through others');
  const bells = async () => (await wes('GET', '/api/notifications')).body.items.filter((n) => /can start/.test(n.title)).length;
  await kay('PATCH', `/api/tasks/tasks/${design.id}`, { done: true });
  assert.equal(await bells(), 0, 'still waiting on the copy');
  await kay('PATCH', `/api/tasks/tasks/${copy.id}`, { done: true });
  assert.equal(await bells(), 1, 'all done: Wes is told');
  const n = (await wes('GET', '/api/notifications')).body.items.find((x) => /can start/.test(x.title));
  assert.equal(n.title, '“Print flyers” can start');
  // Deleting a task it waited on takes it off.
  await kay('DELETE', `/api/tasks/tasks/${copy.id}`);
  const after = (await kay('GET', `/api/tasks/lists/${list}/tasks`)).body.find((t) => t.id === print.id);
  assert.deepEqual(after.blocked_by, [design.id]);
  // Moving it to another list leaves what it waited on behind.
  await kay('PATCH', `/api/tasks/tasks/${print.id}`, { list_id: other });
  assert.deepEqual((await kay('GET', `/api/tasks/lists/${other}/tasks`)).body.find((t) => t.id === print.id).blocked_by, []);
});

test('forms: a linked spreadsheet gets each response as it arrives, and changed ones in their row', async () => {
  const kay = client(); await login(kay, 'kay@keepco.com');
  const anon = client();
  const f = (await kay('POST', '/api/forms', { title: 'Lunch order', questions: [{ id: 'food', type: 'short', title: 'Food' }] })).body;
  await kay('PUT', `/api/forms/${f.id}`, { audience: 'public', allow_edit: true });
  await anon('POST', `/api/public/forms/${f.token}`, { answers: { food: 'Soup' } });
  const made = await kay('POST', `/api/forms/${f.id}/sheet`, { link: true });
  assert.equal(made.status, 201);
  assert.equal(made.body.linked, true);
  assert.equal((await kay('POST', `/api/forms/${f.id}/sheet`, { link: true })).body.id, made.body.id, 'the same one again');
  assert.equal((await kay('GET', `/api/forms/${f.id}`)).body.linked_sheet.id, made.body.id);
  const cells = async () => (await kay('GET', `/api/files/${made.body.id}/content`)).body.content.sheets[0].cells;
  let c = await cells();
  assert.equal(c.A1, 'Submitted'); assert.equal(c.B1, 'Food'); assert.equal(c.C1, 'Response ID'); assert.equal(c.B2, 'Soup');
  // Someone moves the columns about and adds their own notes: new rows still land under the headings.
  const cur = (await kay('GET', `/api/files/${made.body.id}/content`)).body;
  const moved = { ...cur.content.sheets[0].cells, B1: 'Notes', D1: 'Food', D2: 'Soup', B2: 'paid' };
  await kay('PUT', `/api/files/${made.body.id}/content`, { version: cur.file.version, content: { sheets: [{ ...cur.content.sheets[0], cells: moved }] } });
  const sent = (await anon('POST', `/api/public/forms/${f.token}`, { answers: { food: '=1+1' } })).body;
  c = await cells();
  assert.equal(c.D3, "'=1+1", 'under its heading, never a formula');
  assert.equal(c.B3, undefined);
  // A question added later gets a column at the end.
  await kay('PUT', `/api/forms/${f.id}`, { questions: [{ id: 'food', type: 'short', title: 'Food' }, { id: 'drink', type: 'short', title: 'Drink' }] });
  await anon('PUT', `/api/public/forms/${f.token}/response/${sent.edit_key}`, { answers: { food: 'Pie', drink: 'Tea' } });
  c = await cells();
  assert.equal(c.D3, 'Pie', 'a changed response stays in its row');
  assert.equal(c.E1, 'Drink'); assert.equal(c.E3, 'Tea');
  assert.equal(c.D4, undefined);
  // Unlinked: no more rows.
  await kay('DELETE', `/api/forms/${f.id}/sheet`);
  await anon('POST', `/api/public/forms/${f.token}`, { answers: { food: 'Cake' } });
  assert.equal((await cells()).D4, undefined);
  assert.equal((await kay('GET', `/api/forms/${f.id}`)).body.linked_sheet, null);
});

test('signatures: a document sent for signing is locked; each signer signs on their own link', async () => {
  const kay = client(); await login(kay, 'kay@keepco.com');
  assert.equal((await kay('POST', '/api/users', { local: 'sgb', domain: 'keepco.com', name: 'Sid Signer', password: 'password123' })).status, 201);
  const sid = client(); await login(sid, 'sgb@keepco.com');
  const doc = (await kay('POST', '/api/files/new', { kind: 'doc', name: 'Lease', content: { type: 'doc', content: [{ type: 'paragraph', content: [{ type: 'text', text: 'Rent is 1000 a month.' }] }] } })).body;
  const sheet = (await kay('POST', '/api/files/new', { kind: 'sheet', name: 'Not a doc' })).body;
  assert.equal((await kay('POST', '/api/signatures', { file_id: sheet.id, signers: ['sgb@keepco.com'] })).status, 400);
  assert.equal((await kay('POST', '/api/signatures', { file_id: doc.id, signers: ['not an email'] })).status, 400);
  assert.equal((await sid('POST', '/api/signatures', { file_id: doc.id, signers: ['sgb@keepco.com'] })).status, 404, 'needs the document');
  const made = await kay('POST', '/api/signatures', { file_id: doc.id, signers: ['sgb@keepco.com', 'kay@keepco.com'], message: 'Please sign by Friday' });
  assert.equal(made.status, 201);
  assert.equal(made.body.status, 'pending');
  assert.match(made.body.hash, /^[0-9a-f]{64}$/);
  assert.ok(made.body.signers.find((x) => x.email === 'kay@keepco.com').my_link, 'your own link to sign');
  assert.equal((await kay('POST', '/api/signatures', { file_id: doc.id, signers: ['sgb@keepco.com'] })).status, 400, 'one at a time');
  // Locked while it's out.
  assert.equal((await kay('PUT', `/api/files/${doc.id}/content`, { version: 1, content: { type: 'doc', content: [] } })).status, 423);
  // Sid got a notification with his link; the link works without the document being shared.
  const n = (await sid('GET', '/api/notifications')).body.items.find((x) => /asked you to sign “Lease”/.test(x.title));
  const token = n.link.split('/sign/')[1];
  const anon = client();
  const page = (await anon('GET', `/api/public/sign/${token}`)).body;
  assert.equal(page.title, 'Lease');
  assert.equal(page.content.content[0].content[0].text, 'Rent is 1000 a month.');
  assert.deepEqual(page.signers.map((x) => x.signed), [false, false]);
  assert.equal((await anon('POST', `/api/public/sign/${token}`, { name: 'Sid Signer', image: null })).status, 400, 'must agree');
  assert.equal((await anon('POST', `/api/public/sign/${token}`, { name: 'Sid', image: 'javascript:alert(1)', agree: true })).status, 400);
  const png = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==';
  const signed = await anon('POST', `/api/public/sign/${token}`, { name: 'Sid Signer', image: png, agree: true });
  assert.equal(signed.status, 200);
  assert.equal(signed.body.me.name, 'Sid Signer');
  assert.equal((await anon('POST', `/api/public/sign/${token}`, { name: 'Again', image: null, agree: true })).status, 400, 'once');
  // The last one completes it.
  const mine = made.body.signers.find((x) => x.email === 'kay@keepco.com').my_link.split('/sign/')[1];
  await kay('POST', `/api/public/sign/${mine}`, { name: 'Kay Keeper', image: null, agree: true });
  const cur = (await kay('GET', `/api/signatures/file/${doc.id}`)).body.current;
  assert.equal(cur.status, 'complete');
  assert.deepEqual(cur.signers.map((x) => [x.name, !!x.signed_at, x.image ? 'drawn' : 'typed']), [['Sid Signer', true, 'drawn'], ['Kay Keeper', true, 'typed']]);
  assert.equal(cur.changed_since, false);
  assert.equal(cur.signers.some((x) => x.token), false, 'links stay private');
  assert.ok((await kay('GET', '/api/notifications')).body.items.some((x) => x.title === 'Everyone has signed “Lease”'));
  assert.equal((await sid('GET', `/api/signatures/file/${doc.id}`)).status, 404, 'signing doesn\'t share the document');
  // Still locked after; unlocking and changing it shows the signed text has changed.
  assert.equal((await kay('PUT', `/api/files/${doc.id}/lock`, { locked: false })).status, 200);
  const v = (await kay('GET', `/api/files/${doc.id}/content`)).body.file.version;
  await kay('PUT', `/api/files/${doc.id}/content`, { version: v, content: { type: 'doc', content: [{ type: 'paragraph', content: [{ type: 'text', text: 'Rent is 900.' }] }] } });
  assert.equal((await kay('GET', `/api/signatures/file/${doc.id}`)).body.current.changed_since, true);
  // Cancelling a new one unlocks it.
  const again = (await kay('POST', '/api/signatures', { file_id: doc.id, signers: ['sgb@keepco.com'] })).body;
  assert.equal((await kay('POST', `/api/signatures/${again.id}/cancel`)).status, 200);
  assert.equal((await anon('GET', `/api/public/sign/${token}`)).status, 200, 'the finished one is still readable by its signer');
  assert.equal((await kay('GET', `/api/files/${doc.id}`)).body.locked_at, null);
});

