test('meet recording: everyone is told who is recording; recordings go to a Meet recordings folder', { timeout: 20000 }, async () => {
  const { default: WS } = await import('ws');
  const kay = client(); await login(kay, 'kay@keepco.com');
  await kay('POST', '/api/users', { local: 'mrec', domain: 'keepco.com', name: 'Rex Recorder', password: 'password123' });
  const cookieOf = async (u) => (await fetch(`${base}/api/auth/login`, { method: 'POST', headers: { 'x-requested-with': 'nas-workspace', 'content-type': 'application/json' }, body: JSON.stringify({ username: u, password: 'password123' }) })).headers.get('set-cookie').split(';')[0];
  const { code } = (await kay('POST', '/api/meet', { title: 'Recorded' })).body;
  const open = (cookie) => new Promise((resolve, reject) => {
    const ws = new WS(`${base.replace('http', 'ws')}/ws/meet/${code}`, { headers: { cookie } });
    ws.msgs = [];
    ws.on('message', (d) => { const m = JSON.parse(String(d)); ws.msgs.push(m); if (m.type === 'welcome') resolve(ws); });
    ws.on('error', reject);
    ws.on('unexpected-response', (rq, res) => reject(new Error(`refused: ${res.statusCode}`)));
    ws.on('close', (c, why) => reject(new Error(`closed ${c} ${why}`)));
    const t = setTimeout(() => reject(new Error('no welcome')), 5000);
    ws.on('message', () => clearTimeout(t));
  });
  const a = await open(await cookieOf('kay@keepco.com'));
  const b = await open(await cookieOf('mrec@keepco.com'));
  try {
    b.send(JSON.stringify({ type: 'state', state: { rec: true } }));
    await new Promise((r) => setTimeout(r, 200));
    const seen = a.msgs.find((m) => m.type === 'state' && m.state.rec === true);
    assert.ok(seen, 'the others see that someone is recording');
    assert.equal(seen.state.mic, true, 'the rest of their state stays');
  } finally { a.terminate(); b.terminate(); }
  const f1 = (await kay('POST', '/api/meet/recordings-folder')).body.id;
  assert.equal((await kay('POST', '/api/meet/recordings-folder')).body.id, f1, 'the same folder each time');
  const up = (await kay('POST', `/api/files/upload?parent=${f1}&name=${encodeURIComponent('Recorded 2026-11-08 14.50.webm')}`, Buffer.alloc(3000, 1), { raw: true })).body;
  assert.equal(up.mime, 'video/webm');
  assert.equal(up.parent_id, f1);
});

test('meet host controls: the host mutes someone or everyone, and removes someone, who can\'t come back', { timeout: 20000 }, async () => {
  const { default: WS } = await import('ws');
  const kay = client(); await login(kay, 'kay@keepco.com');
  for (const [local, name] of [['mhb', 'Hal Guest'], ['mhc', 'Cass Guest']]) await kay('POST', '/api/users', { local, domain: 'keepco.com', name, password: 'password123' });
  const cookieOf = async (u) => (await fetch(`${base}/api/auth/login`, { method: 'POST', headers: { 'x-requested-with': 'nas-workspace', 'content-type': 'application/json' }, body: JSON.stringify({ username: u, password: 'password123' }) })).headers.get('set-cookie').split(';')[0];
  const { code } = (await kay('POST', '/api/meet', { title: 'Hosted' })).body;
  const open = (cookie) => new Promise((resolve, reject) => {
    const ws = new WS(`${base.replace('http', 'ws')}/ws/meet/${code}`, { headers: { cookie } });
    ws.msgs = [];
    const t = setTimeout(() => reject(new Error('no welcome')), 5000);
    ws.on('message', (d) => { const msg = JSON.parse(String(d)); ws.msgs.push(msg); if (msg.type === 'welcome') { clearTimeout(t); ws.me = msg; resolve(ws); } });
    ws.on('close', (c, why) => { ws.closed = [c, String(why)]; clearTimeout(t); reject(new Error(`closed ${c} ${why}`)); });
    ws.on('error', reject);
  });
  const host = await open(await cookieOf('kay@keepco.com'));
  const hal = await open(await cookieOf('mhb@keepco.com'));
  const cass = await open(await cookieOf('mhc@keepco.com'));
  const wait = () => new Promise((r) => setTimeout(r, 200));
  try {
    assert.equal(host.me.host, true); assert.equal(hal.me.host, false);
    // Only the host can.
    hal.send(JSON.stringify({ type: 'mute', to: cass.me.id })); await wait();
    assert.ok(!cass.msgs.some((m) => m.type === 'muted'));
    host.send(JSON.stringify({ type: 'mute', to: hal.me.id })); await wait();
    assert.deepEqual(hal.msgs.find((m) => m.type === 'muted'), { type: 'muted', by: 'Kay Keep' });
    assert.ok(!cass.msgs.some((m) => m.type === 'muted'));
    host.send(JSON.stringify({ type: 'mute', to: 'all' })); await wait();
    assert.ok(cass.msgs.some((m) => m.type === 'muted'));
    assert.ok(!host.msgs.some((m) => m.type === 'muted'), 'not the host');
    host.send(JSON.stringify({ type: 'remove', to: cass.me.id })); await wait();
    assert.equal(cass.closed?.[0], 4003);
    assert.match(cass.closed[1], /removed you/);
    assert.ok(host.msgs.some((m) => m.type === 'left' && m.id === cass.me.id));
    await assert.rejects(open(await cookieOf('mhc@keepco.com')), /4003/, 'can\'t come back');
  } finally { host.terminate(); hal.terminate(); cass.terminate(); }
});

test('meet lock: the host locks a meeting, nobody new comes in, those inside can come back; unlock', { timeout: 20000 }, async () => {
  const { default: WS } = await import('ws');
  const kay = client(); await login(kay, 'kay@keepco.com');
  for (const [local, name] of [['mlb', 'Lia Lock'], ['mlc', 'Cy Late']]) await kay('POST', '/api/users', { local, domain: 'keepco.com', name, password: 'password123' });
  const cookieOf = async (u) => (await fetch(`${base}/api/auth/login`, { method: 'POST', headers: { 'x-requested-with': 'nas-workspace', 'content-type': 'application/json' }, body: JSON.stringify({ username: u, password: 'password123' }) })).headers.get('set-cookie').split(';')[0];
  const { code } = (await kay('POST', '/api/meet', { title: 'Locked' })).body;
  const open = (cookie) => new Promise((resolve, reject) => {
    const ws = new WS(`${base.replace('http', 'ws')}/ws/meet/${code}`, { headers: { cookie } });
    ws.msgs = [];
    const t = setTimeout(() => reject(new Error('no welcome')), 5000);
    ws.on('message', (d) => { const msg = JSON.parse(String(d)); ws.msgs.push(msg); if (msg.type === 'welcome') { clearTimeout(t); ws.me = msg; resolve(ws); } });
    ws.on('close', (c, why) => { ws.closed = [c, String(why)]; clearTimeout(t); reject(new Error(`closed ${c} ${why}`)); });
    ws.on('error', reject);
  });
  const wait = () => new Promise((r) => setTimeout(r, 200));
  const hostCookie = await cookieOf('kay@keepco.com'), liaCookie = await cookieOf('mlb@keepco.com'), cyCookie = await cookieOf('mlc@keepco.com');
  const host = await open(hostCookie);
  let lia = await open(liaCookie);
  const more = [];
  try {
    assert.equal(host.me.locked, false);
    lia.send(JSON.stringify({ type: 'lock', on: true })); await wait();
    assert.ok(!host.msgs.some((m) => m.type === 'locked'), 'only the host can');
    host.send(JSON.stringify({ type: 'lock', on: true })); await wait();
    assert.deepEqual(lia.msgs.find((m) => m.type === 'locked'), { type: 'locked', on: true, by: 'Kay Keep' });
    await assert.rejects(open(cyCookie), /4005.*locked/, 'nobody new');
    // Lia drops and comes back: she was in it.
    lia.terminate(); await wait();
    lia = await open(liaCookie);
    assert.equal(lia.me.locked, true);
    // Open again: Cy can join.
    host.send(JSON.stringify({ type: 'lock', on: false })); await wait();
    assert.ok(lia.msgs.some((m) => m.type === 'locked' && m.on === false));
    more.push(await open(cyCookie));
    // Locked again, then everyone leaves: the next meeting there starts open.
    host.send(JSON.stringify({ type: 'lock', on: true })); await wait();
    host.terminate(); lia.terminate(); more[0].terminate(); await wait();
    const again = await open(cyCookie);
    more.push(again);
    assert.equal(again.me.locked, false);
  } finally { host.terminate(); lia.terminate(); for (const w of more) w.terminate(); }
});

