test('Excel downloads: form responses and a task list', async () => {
  const ExcelJS = (await import('exceljs')).default;
  const read = async (body) => { const wb = new ExcelJS.Workbook(); await wb.xlsx.load(Buffer.from(body)); return wb.worksheets[0]; };
  const a = client(), b = client();
  for (const [local, name] of [['xlsxa', 'Xl Ann'], ['xlsxb', 'Xl Ben']]) assert.equal((await owner('POST', '/api/users', { local, domain: 'acme.com', name, password: 'password123' })).status, 201);
  await login(a, 'xlsxa@acme.com');
  await login(b, 'xlsxb@acme.com');
  const f = (await a('PUT', `/api/forms/${(await a('POST', '/api/forms', { title: 'Lunch' })).body.id}`, { questions: [{ id: 'food', type: 'short', title: 'Food' }] })).body;
  await b('POST', `/api/public/forms/${f.token}`, { answers: { food: '=HYPERLINK("x")' } });
  const x = await a('GET', `/api/forms/${f.id}/responses.xlsx`, undefined, { binary: true });
  assert.equal(x.status, 200);
  assert.match(x.headers.get('content-type'), /spreadsheetml/);
  assert.match(x.headers.get('content-disposition'), /Lunch%20responses\.xlsx/);
  const ws = await read(x.body);
  assert.deepEqual([ws.getCell('A1').value, ws.getCell('D1').value], ['Submitted', 'Food']);
  assert.equal(ws.getCell('D2').value, '=HYPERLINK("x")', 'an answer is never a formula');
  assert.equal((await b('GET', `/api/forms/${f.id}/responses.xlsx`)).status, 404, 'only its owner and editors');

  const list = (await a('POST', '/api/tasks/lists', { name: 'Launch' })).body;
  await a('POST', `/api/tasks/lists/${list.id}/tasks`, { title: 'Book venue', due: '2026-12-01' });
  const t = await a('GET', `/api/tasks/lists/${list.id}/export.xlsx`, undefined, { binary: true });
  assert.equal(t.status, 200);
  const tw = await read(t.body);
  assert.equal(tw.name, 'Launch');
  assert.deepEqual([tw.getCell('A1').value, tw.getCell('A2').value], ['Task', 'Book venue']);
  assert.ok(tw.getCell('C2').value instanceof Date, 'the due date as a date');
  assert.equal((await b('GET', `/api/tasks/lists/${list.id}/export.xlsx`)).status, 404);
});

test('forms: email me each response, for each person on the team', async () => {
  const { responseEmail } = await import('../src/routes/forms.js');
  const form = { title: 'Lunch', questions: [{ id: 'a', type: 'short', title: 'Name' }, { id: 'b', type: 'choice', title: 'Food', options: ['Pizza'] }] };
  const m = responseEmail(form, { a: 'Ana', b: 'Pizza' }, { who: 'Ana Lee', score: { score: 1, max: 2 }, link: 'https://x/forms/1?tab=responses' });
  assert.equal(m.subject, 'New response to “Lunch” from Ana Lee');
  assert.match(m.text, /^A new response to “Lunch” from Ana Lee:\n\nName: Ana\nFood: Pizza\n\nScore: 1 \/ 2\n\nAll responses: https:\/\/x\/forms\/1\?tab=responses\n/);
  const anon = responseEmail(form, { a: 'Bo' }, { email: 'bo@example.com' });
  assert.equal(anon.subject, 'New response to “Lunch” from bo@example.com');
  assert.match(anon.text, /^A new response to “Lunch” \(bo@example\.com\):/);
  assert.equal(responseEmail(form, {}).subject, 'New response to “Lunch”');

  const own = client(); const ed = client(); const other = client();
  for (const [local, name] of [['emo', 'Em Owner'], ['eme', 'Em Editor'], ['emx', 'Em Other']]) {
    assert.equal((await owner('POST', '/api/users', { local, domain: 'acme.com', name, password: 'password123' })).status, 201);
  }
  await login(own, 'emo@acme.com'); await login(ed, 'eme@acme.com'); await login(other, 'emx@acme.com');
  const f = (await own('POST', '/api/forms', { title: 'Ideas' })).body;
  await own('POST', `/api/forms/${f.id}/editors`, { email: 'eme@acme.com' });
  assert.equal((await own('GET', `/api/forms/${f.id}`)).body.email_me, false);
  assert.equal((await own('GET', `/api/forms/${f.id}`)).body.mail, false, 'this server has no email');
  assert.deepEqual((await own('PUT', `/api/forms/${f.id}/email-me`, { on: true })).body, { email_me: true });
  assert.equal((await own('GET', `/api/forms/${f.id}`)).body.email_me, true);
  assert.equal((await ed('GET', `/api/forms/${f.id}`)).body.email_me, false, 'each person chooses for themselves');
  await ed('PUT', `/api/forms/${f.id}/email-me`, { on: true });
  assert.equal((await ed('GET', `/api/forms/${f.id}`)).body.email_me, true);
  await ed('PUT', `/api/forms/${f.id}/email-me`, { on: false });
  assert.equal((await ed('GET', `/api/forms/${f.id}`)).body.email_me, false);
  assert.equal((await other('PUT', `/api/forms/${f.id}/email-me`, { on: true })).status, 404, 'only the team');
  // Sending a response still works (no email here).
  assert.equal((await other('POST', `/api/public/forms/${f.token}`, { answers: {} })).status, 201);
});

test('forms: opening automatically at a set time', async () => {
  const own = client();
  assert.equal((await owner('POST', '/api/users', { local: 'opn', domain: 'acme.com', name: 'Opal Owner', password: 'password123' })).status, 201);
  await login(own, 'opn@acme.com');
  const f = (await own('POST', '/api/forms', { title: 'Course sign-up', questions: [{ id: 'q', type: 'short', title: 'Name' }] })).body;
  await own('PUT', `/api/forms/${f.id}`, { audience: 'public' });
  const later = Date.now() + 3600e3;
  const set = (await own('PUT', `/api/forms/${f.id}`, { open_at: later })).body;
  assert.equal(set.open_at, later);
  assert.equal(set.closed, 'notyet');
  assert.equal((await own('GET', '/api/forms')).body.find((x) => x.id === f.id).closed, 'notyet', 'the list says so too');
  const anon = client();
  const pub = (await anon('GET', `/api/public/forms/${f.token}`)).body;
  assert.deepEqual([pub.accepting, pub.closed, pub.opens_at, pub.closed_text], [false, 'notyet', later, "This form isn't open yet"]);
  const early = await anon('POST', `/api/public/forms/${f.token}`, { answers: { q: 'Ana' } });
  assert.equal(early.status, 409);
  assert.match(early.body.error, /isn't open yet/);
  // Opening has to come before closing.
  assert.equal((await own('PUT', `/api/forms/${f.id}`, { close_at: later - 60e3 })).status, 400);
  assert.equal((await own('PUT', `/api/forms/${f.id}`, { open_at: 'soon' })).status, 400);
  // Once the time has come (here: set in the past), it takes answers.
  assert.equal((await own('PUT', `/api/forms/${f.id}`, { open_at: Date.now() - 1000, close_at: later })).body.closed, null);
  const pub2 = (await anon('GET', `/api/public/forms/${f.token}`)).body;
  assert.deepEqual([pub2.accepting, pub2.opens_at], [true, undefined]);
  assert.equal((await anon('POST', `/api/public/forms/${f.token}`, { answers: { q: 'Ana' } })).status, 201);
  assert.equal((await own('PUT', `/api/forms/${f.id}`, { open_at: null })).body.open_at, null);
});

test('Office files: replies and resolved comments in a Word file', async () => {
  const { Document, Packer, Paragraph, TextRun, CommentRangeStart, CommentRangeEnd, CommentReference } = await import('docx');
  const docx = await Packer.toBuffer(new Document({
    comments: { children: [
      { id: 0, author: 'Jane Smith', date: new Date('2026-10-01T10:00:00Z'), children: [new Paragraph('Is this right?')] },
      { id: 1, author: 'Raj Patel', date: new Date('2026-10-02T10:00:00Z'), parentId: 0, children: [new Paragraph('Yes, checked.')] },
      { id: 2, author: 'Jane Smith', date: new Date('2026-10-03T10:00:00Z'), children: [new Paragraph('Old note')], resolved: true },
    ] },
    sections: [{ children: [new Paragraph({ children: [
      new CommentRangeStart(0), new CommentRangeStart(1), new TextRun('Sales'), new CommentRangeEnd(0), new CommentRangeEnd(1), new TextRun({ children: [new CommentReference(0)] }), new TextRun({ children: [new CommentReference(1)] }),
      new TextRun(' and '), new CommentRangeStart(2), new TextRun('costs'), new CommentRangeEnd(2), new TextRun({ children: [new CommentReference(2)] }),
    ] })] }],
  }));
  const up = (await owner('POST', '/api/files/upload?name=Threads.docx', docx, { raw: true })).body;
  const opened = (await owner('POST', `/api/files/${up.id}/open-as`)).body;
  const all = (await owner('GET', `/api/comments/${opened.id}`)).body;
  const top = all.filter((c) => !c.thread_id);
  assert.equal(top.length, 2, 'the reply is not a thread of its own');
  const sales = top.find((c) => c.anchor.quote === 'Sales');
  assert.deepEqual(all.filter((c) => c.thread_id === sales.id).map((c) => c.body), ['Yes, checked.\n\n— Raj Patel (in the Word file)']);
  assert.equal(top.find((c) => c.anchor.quote === 'costs').resolved, true);
  assert.equal(sales.resolved, false);
});

test('Office files: comments in a Word file become comment threads on the document', async () => {
  const { Document, Packer, Paragraph, TextRun, CommentRangeStart, CommentRangeEnd, CommentReference } = await import('docx');
  const docx = await Packer.toBuffer(new Document({
    comments: { children: [{ id: 0, author: 'Jane Smith', date: new Date('2026-10-01T10:00:00Z'), children: [new Paragraph('Can we check this figure?')] }] },
    sections: [{ children: [new Paragraph({ children: [new TextRun('Revenue grew by '), new CommentRangeStart(0), new TextRun('12 percent'), new CommentRangeEnd(0), new TextRun({ children: [new CommentReference(0)] })] })] }],
  }));
  const up = (await owner('POST', '/api/files/upload?name=Reviewed.docx', docx, { raw: true })).body;
  const opened = (await owner('POST', `/api/files/${up.id}/open-as`)).body;
  const threads = (await owner('GET', `/api/comments/${opened.id}`)).body;
  assert.equal(threads.length, 1);
  assert.equal(threads[0].body, 'Can we check this figure?\n\n— Jane Smith (in the Word file)');
  assert.deepEqual(threads[0].anchor, { quote: '12 percent' });
  assert.equal(threads[0].created_at, Date.parse('2026-10-01T10:00:00Z'));
  const content = JSON.stringify((await owner('GET', `/api/files/${opened.id}/content`)).body.content);
  assert.ok(content.includes(`"type":"comment","attrs":{"id":"${threads[0].id}"}`), 'its words are marked with the thread');
  // A reply, then the Word download: the thread goes back as a Word comment, with the reply.
  assert.equal((await owner('POST', `/api/comments/${opened.id}`, { body: 'Checked, it is right', thread_id: threads[0].id })).status, 201);
  const { docFromWord } = await import('../src/office/word.js');
  const out = await owner('GET', `/api/files/${opened.id}/export`, undefined, { binary: true });
  const back = await docFromWord(out.body);
  assert.equal(back.comments.length, 1);
  assert.equal(back.comments[0].quote, '12 percent');
  assert.equal(back.comments[0].text, 'Can we check this figure?\n\n— Jane Smith (in the Word file)');
  assert.deepEqual(back.comments[0].replies.map((r) => r.text), ['Checked, it is right'], 'the reply goes out as a Word reply');
  // Resolved threads stay out.
  assert.equal((await owner('PATCH', `/api/comments/${opened.id}/${threads[0].id}`, { resolved: true })).status, 200);
  assert.deepEqual((await docFromWord((await owner('GET', `/api/files/${opened.id}/export`, undefined, { binary: true })).body)).comments, []);
});

