test('PDF organise pages: reorder, turn, leave out; as a copy or a new version (the old one kept)', async () => {
  const { PDFDocument } = await import('pdf-lib');
  const d = await PDFDocument.create(); for (let i = 0; i < 4; i++) d.addPage([100 + i, 200]);
  const hal = client(), viewer = client();
  for (const [local, name] of [['pdfhal', 'Pdf Hal'], ['pdfvic', 'Pdf Vic']]) assert.equal((await owner('POST', '/api/users', { local, domain: 'acme.com', name, password: 'password123' })).status, 201);
  await login(hal, 'pdfhal@acme.com'); await login(viewer, 'pdfvic@acme.com');
  const f = (await hal('POST', '/api/files/upload?name=Scan.pdf', Buffer.from(await d.save()), { raw: true, headers: { 'content-type': 'application/octet-stream' } })).body;
  const widths = async (id, who = hal) => (await PDFDocument.load((await who('GET', `/api/files/${id}/raw`, undefined, { binary: true })).body)).getPages().map((p) => [Math.round(p.getWidth()), p.getRotation().angle]);
  assert.equal((await hal('POST', `/api/files/${f.id}/pdf/organize`, { pages: [] })).status, 400);
  assert.match((await hal('POST', `/api/files/${f.id}/pdf/organize`, { pages: [{ page: 9 }] })).body.error, /has 4 pages/);
  const copy = await hal('POST', `/api/files/${f.id}/pdf/organize`, { pages: [{ page: 3 }, { page: 0, rotate: 90 }], as: 'copy' });
  assert.equal(copy.status, 201);
  assert.equal(copy.body.name, 'Scan (reorganised).pdf');
  assert.deepEqual(await widths(copy.body.id), [[103, 0], [100, 90]]);
  // As a new version: the same file, one more version; the old pages are in its history.
  const v = await hal('POST', `/api/files/${f.id}/pdf/organize`, { pages: [{ page: 1 }, { page: 2, rotate: 180 }], as: 'version' });
  assert.equal(v.status, 200, JSON.stringify(v.body));
  assert.equal(v.body.id, f.id);
  assert.deepEqual(await widths(f.id), [[101, 0], [102, 180]]);
  const versions = (await hal('GET', `/api/files/${f.id}/versions`)).body;
  assert.ok((versions.versions || versions).length >= 1, JSON.stringify(versions).slice(0, 200));
  // A viewer can make a copy, not a new version.
  await hal('PUT', `/api/files/${f.id}/shares`, { shares: [{ user_id: (await viewer('GET', '/api/auth/me')).body.user.id, role: 'viewer' }] });
  assert.equal((await viewer('POST', `/api/files/${f.id}/pdf/organize`, { pages: [{ page: 0 }], as: 'version' })).status, 403);
  assert.equal((await viewer('POST', `/api/files/${f.id}/pdf/organize`, { pages: [{ page: 0 }], as: 'copy' })).status, 201);
});

test('PDF sent for signature: signers see the PDF as sent; when all have signed, a signed copy with a Signatures page', async () => {
  const { PDFDocument } = await import('pdf-lib');
  const d = await PDFDocument.create(); d.addPage([595, 842]); d.addPage([595, 842]);
  const ida = client(), jon = client(), kai = client();
  for (const [local, name] of [['sigida', 'Ida Sender'], ['sigjon', 'Jon Signer'], ['sigkai', 'Kai Signer']]) assert.equal((await owner('POST', '/api/users', { local, domain: 'acme.com', name, password: 'password123' })).status, 201);
  await login(ida, 'sigida@acme.com'); await login(jon, 'sigjon@acme.com'); await login(kai, 'sigkai@acme.com');
  const f = (await ida('POST', '/api/files/upload?name=Lease.pdf', Buffer.from(await d.save()), { raw: true, headers: { 'content-type': 'application/octet-stream' } })).body;
  const txt = (await ida('POST', '/api/files/upload?name=notes.txt', 'hi', { raw: true, headers: { 'content-type': 'text/plain' } })).body;
  assert.match((await ida('POST', '/api/signatures', { file_id: txt.id, signers: ['sigjon@acme.com'] })).body.error, /documents and PDFs/);
  const sent = await ida('POST', '/api/signatures', { file_id: f.id, signers: ['sigjon@acme.com', 'sigkai@acme.com'], in_order: true, message: 'Please sign the lease' });
  assert.equal(sent.status, 201, JSON.stringify(sent.body));
  assert.equal(sent.body.pdf, true);
  assert.equal((await ida('GET', `/api/files/${f.id}`)).body.locked_at > 0, true, 'locked while it is out');
  const link = async (who) => (await who('GET', '/api/signatures')).body.waiting[0]?.link;
  const jonLink = await link(jon);
  assert.ok(jonLink);
  assert.equal(await link(kai), undefined, 'in order: Kai waits');
  const token = jonLink.split('/').pop();
  const pub = (await fetch(`${base}/api/public/sign/${token}`).then((r) => r.json()));
  assert.deepEqual(pub.content, { pdf: true });
  const pdfBytes = Buffer.from(await (await fetch(`${base}/api/public/sign/${token}/pdf`)).arrayBuffer());
  assert.equal((await PDFDocument.load(pdfBytes)).getPageCount(), 2, 'the PDF as sent, through the private link');
  const png = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAABCAYAAAD0In+KAAAAEUlEQVR4nGP4z8DwHwQZGBgAOe4F+3cjr+0AAAAASUVORK5CYII=';
  const signAs = (tok, body) => fetch(`${base}/api/public/sign/${tok}`, { method: 'POST', headers: { 'content-type': 'application/json', 'x-requested-with': 'nas-workspace' }, body: JSON.stringify(body) }).then(async (r) => ({ status: r.status, body: await r.json() }));
  assert.equal((await signAs(token, { name: 'Jon Signer', image: png, agree: true })).status, 200);
  const kaiTok = (await link(kai)).split('/').pop();
  const done = await signAs(kaiTok, { name: 'Kai Signer', image: null, agree: true });
  assert.equal(done.body.status, 'complete');
  // The signed copy: beside the original, owned by the sender, the PDF's pages plus a Signatures page.
  const mine = (await ida('GET', '/api/signatures')).body.sent[0];
  assert.equal(mine.status, 'complete');
  assert.ok(mine.signed_file_id);
  const signed = (await ida('GET', `/api/files/${mine.signed_file_id}`)).body;
  assert.equal(signed.name, 'Lease (signed).pdf');
  const out = await PDFDocument.load((await ida('GET', `/api/files/${mine.signed_file_id}/raw`, undefined, { binary: true })).body);
  assert.equal(out.getPageCount(), 3);
  assert.equal(mine.changed_since, false);
  const bell = JSON.stringify((await ida('GET', '/api/notifications')).body);
  assert.ok(bell.includes('Everyone has signed “Lease.pdf”') && bell.includes('/drive/signatures'));
});

test('PDF signature boxes: the sender places them per signer; signatures and dates are drawn in them', async () => {
  const { PDFDocument, PDFName } = await import('pdf-lib');
  const d = await PDFDocument.create(); d.addPage([595, 842]); d.addPage([595, 842]);
  const lia = client(), mo = client();
  for (const [local, name] of [['boxlia', 'Lia Sender'], ['boxmo', 'Mo Signer']]) assert.equal((await owner('POST', '/api/users', { local, domain: 'acme.com', name, password: 'password123' })).status, 201);
  await login(lia, 'boxlia@acme.com'); await login(mo, 'boxmo@acme.com');
  const f = (await lia('POST', '/api/files/upload?name=Offer.pdf', Buffer.from(await d.save()), { raw: true, headers: { 'content-type': 'application/octet-stream' } })).body;
  const send = (fields) => lia('POST', '/api/signatures', { file_id: f.id, signers: ['boxmo@acme.com', 'boxlia@acme.com'], fields });
  assert.match((await send([{ email: 'someone@else.com', page: 0, x: 0.1, y: 0.1, w: 0.3, h: 0.05 }])).body.error, /isn’t one of the signers/);
  assert.match((await send([{ email: 'boxmo@acme.com', page: 5, x: 0.1, y: 0.1, w: 0.3, h: 0.05 }])).body.error, /has 2 pages/);
  assert.match((await send([{ email: 'boxmo@acme.com', page: 0, x: 1.5, y: 0.1, w: 0.3, h: 0.05 }])).body.error, /off the page/);
  const sent = await send([
    { email: 'boxmo@acme.com', page: 0, x: 0.55, y: 0.8, w: 0.35, h: 0.06, type: 'signature' },
    { email: 'boxmo@acme.com', page: 0, x: 0.55, y: 0.87, w: 0.25, h: 0.025, type: 'date' },
    { email: 'boxlia@acme.com', page: 1, x: 0.1, y: 0.8, w: 0.35, h: 0.06, type: 'signature' },
  ]);
  assert.equal(sent.status, 201, JSON.stringify(sent.body));
  assert.equal(sent.body.boxes, 3);
  const tokenOf = async (who) => (await who('GET', '/api/signatures')).body.waiting[0].link.split('/').pop();
  const moTok = await tokenOf(mo), liaTok = await tokenOf(lia);
  const pub = await fetch(`${base}/api/public/sign/${moTok}`).then((r) => r.json());
  assert.deepEqual(pub.my_boxes.map((b) => [b.page, b.type]), [[0, 'signature'], [0, 'date']], 'Mo sees only his boxes');
  const png = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAABCAYAAAD0In+KAAAAEUlEQVR4nGP4z8DwHwQZGBgAOe4F+3cjr+0AAAAASUVORK5CYII=';
  const signAs = (tok, body) => fetch(`${base}/api/public/sign/${tok}`, { method: 'POST', headers: { 'content-type': 'application/json', 'x-requested-with': 'nas-workspace' }, body: JSON.stringify(body) }).then((r) => r.json());
  await signAs(moTok, { name: 'Mo Signer', image: png, agree: true });
  assert.equal((await signAs(liaTok, { name: 'Lia Sender', image: null, agree: true })).status, 'complete');
  const done = (await lia('GET', '/api/signatures')).body.sent.find((x) => x.file_id === f.id);
  const out = await PDFDocument.load((await lia('GET', `/api/files/${done.signed_file_id}/raw`, undefined, { binary: true })).body);
  assert.equal(out.getPageCount(), 3);
  // Page 1 carries Mo's drawn signature (a picture); page 2 Lia's typed one (text); then the Signatures page.
  const pics = (i) => out.getPages()[i].node.Resources()?.lookup(PDFName.of('XObject'))?.keys().length || 0;
  const fonts = (i) => out.getPages()[i].node.Resources()?.lookup(PDFName.of('Font'))?.keys().length || 0;
  assert.equal(pics(0), 1);
  assert.ok(fonts(0) >= 1, 'the date is written');
  assert.ok(fonts(1) >= 1, 'the typed signature is written');
});

