test('mail: forwarding all mail — the Sieve block, confirmation codes, and companies that keep mail inside', async () => {
  const { userSieve } = await import('../src/mail/sieve.js');
  const f = await import('../src/mail/forwarding.js');
  const { buildMailConfig } = await import('../src/mail/config.js');
  const { q } = await import('../src/db.js');
  const s = (keep) => userSieve({ username: 'k@x.com', forward: { address: 'me@home.example', keep } });
  assert.match(s('inbox'), /# Forwarding all mail to me@home\.example\nredirect :copy "me@home\.example";\n/);
  assert.ok(!/fileinto |addflag /.test(s('inbox')), 'your copy stays in the Inbox, as it is');
  assert.match(s('read'), /redirect :copy "me@home\.example";\naddflag "\\\\Seen";/);
  assert.match(s('archive'), /fileinto :create "Archive";\nset "done" "1";/);
  assert.match(s('trash'), /addflag "\\\\Seen";\nfileinto :create "Trash";\nset "done" "1";/);
  const muted = userSieve({ username: 'k@x.com', forward: { address: 'a@b.cd', keep: 'archive' }, muted: ['<t@x>'] });
  assert.ok(muted.indexOf('redirect :copy') < muted.indexOf('# Muted'), 'forwarding comes before everything else');
  // Codes: right, wrong, expired, too many tries.
  const row = { code_hash: f.hashCode('123456'), code_sent_at: Date.now(), tries: 0 };
  assert.equal(f.checkCode(row, '123 456'), 'ok');
  assert.equal(f.checkCode(row, '654321'), 'wrong');
  assert.equal(f.checkCode({ ...row, code_sent_at: Date.now() - (f.CODE_DAYS + 1) * 86400000 }, '123456'), 'expired');
  assert.equal(f.checkCode({ ...row, tries: f.MAX_TRIES }, '123456'), 'locked');
  assert.equal(f.checkCode({ ...row, code_hash: null }, '123456'), 'expired');
  assert.match(f.newCode(), /^\d{6}$/);
  assert.equal(f.cleanAddress(' Me@Home.Example '), 'me@home.example');
  assert.equal(f.cleanAddress('Me <me@home.example>'), null);
  assert.equal(f.recentSends({ sends: JSON.stringify([Date.now() - 2 * 86400000, Date.now() - 1000]) }).length, 1);
  // Inside or outside the company, and the config the mail server gets.
  const u = q(`SELECT u.id, u.org_id, u.username FROM users u WHERE EXISTS (SELECT 1 FROM domains d WHERE d.org_id = u.org_id) AND u.disabled = 0 LIMIT 1`).get();
  const domain = q('SELECT name FROM domains WHERE org_id = ?').get(u.org_id).name;
  assert.ok(f.insideCompany(u.org_id, `x@${domain}`));
  assert.ok(!f.insideCompany(u.org_id, 'x@elsewhere.example'));
  q(`INSERT INTO mail_forwarding (user_id, address, confirmed, enabled, keep) VALUES (?, 'me@elsewhere.example', 1, 1, 'archive')`).run(u.id);
  q('INSERT OR REPLACE INTO mail_rules (user_id, rules, updated_at) VALUES (?, ?, 0)').run(u.id, JSON.stringify([{ name: 'Copy', enabled: true, match: 'all', conditions: [{ field: 'subject', op: 'contains', value: 'x' }], actions: { forwardTo: 'boss@elsewhere.example', star: true, stop: true } }]));
  try {
    let sieve = buildMailConfig()[`sieve/${u.username}.sieve`];
    assert.match(sieve, /redirect :copy "me@elsewhere\.example";\nfileinto :create "Archive";/);
    assert.match(sieve, /redirect :copy "boss@elsewhere\.example";/);
    q('UPDATE orgs SET allow_forwarding = 0 WHERE id = ?').run(u.org_id);
    assert.ok(!f.forwardingAllowed(u.org_id, 'me@elsewhere.example'));
    assert.ok(f.forwardingAllowed(u.org_id, `me@${domain}`));
    sieve = buildMailConfig()[`sieve/${u.username}.sieve`];
    assert.ok(!/elsewhere/.test(sieve), 'nothing goes outside: neither forwarding nor filters’ copies');
    assert.match(sieve, /addflag "\\\\Flagged";/, 'the filter still stars');
    q('UPDATE mail_forwarding SET address = ? WHERE user_id = ?').run(`me2@${domain}`, u.id);
    assert.match(buildMailConfig()[`sieve/${u.username}.sieve`], new RegExp(`redirect :copy "me2@${domain.replace(/\./g, '\\.')}";`), 'inside the company is fine');
    q('UPDATE mail_forwarding SET enabled = 0 WHERE user_id = ?').run(u.id);
    assert.ok(!/me2@/.test(buildMailConfig()[`sieve/${u.username}.sieve`]), 'turned off: no forwarding');
  } finally {
    q('UPDATE orgs SET allow_forwarding = 1 WHERE id = ?').run(u.org_id);
    q('DELETE FROM mail_forwarding WHERE user_id = ?').run(u.id);
    q('DELETE FROM mail_rules WHERE user_id = ?').run(u.id);
  }
});

test('chat drafts: kept per person and conversation, on every device; sending clears it; not for conversations you can’t see', async () => {
  const a = client(), a2 = client(), b = client(), x = client();
  for (const [local, name] of [['dra', 'Draft Ann'], ['drb', 'Draft Ben'], ['drx', 'Draft Xavi']]) assert.equal((await owner('POST', '/api/users', { local, domain: 'acme.com', name, password: 'password123' })).status, 201);
  await login(a, 'dra@acme.com'); await login(a2, 'dra@acme.com');
  const bid = (await login(b, 'drb@acme.com')).id;
  await login(x, 'drx@acme.com');
  const dm = (await a('POST', '/api/chat/dm', { user_id: bid })).body.id;
  assert.deepEqual((await a('GET', '/api/chat/drafts')).body, {});
  const saved = (await a('PUT', `/api/chat/channels/${dm}/draft`, { body: 'Half a thought…' })).body;
  assert.equal(saved.body, 'Half a thought…');
  assert.equal((await a2('GET', '/api/chat/drafts')).body[dm].body, 'Half a thought…', 'on the other device too');
  assert.deepEqual((await b('GET', '/api/chat/drafts')).body, {}, 'only yours');
  assert.equal((await x('PUT', `/api/chat/channels/${dm}/draft`, { body: 'sneaky' })).status, 404, 'not in a conversation you can’t see');
  assert.equal((await a('PUT', `/api/chat/channels/${dm}/draft`, { body: 'x'.repeat(20001) })).status, 400);
  // A thread reply doesn't clear the conversation's draft; sending in it does.
  const first = (await b('POST', `/api/chat/channels/${dm}/messages`, { body: 'Hi' })).body.id;
  await a('POST', `/api/chat/channels/${dm}/messages`, { body: 'In a thread', parent_id: first });
  assert.equal((await a('GET', '/api/chat/drafts')).body[dm]?.body, 'Half a thought…');
  await a('POST', `/api/chat/channels/${dm}/messages`, { body: 'Half a thought, finished' });
  assert.deepEqual((await a('GET', '/api/chat/drafts')).body, {}, 'sent: gone');
  // Emptying it removes it.
  await a('PUT', `/api/chat/channels/${dm}/draft`, { body: 'again' });
  await a('PUT', `/api/chat/channels/${dm}/draft`, { body: '   ' });
  assert.deepEqual((await a('GET', '/api/chat/drafts')).body, {});
});

test('contacts trash: deleted contacts are kept (with their photo) and can be put back as they were; for good after 30 days', async () => {
  const a = client(), b = client();
  for (const [local, name] of [['ctra', 'Trash Ann'], ['ctrb', 'Trash Ben']]) assert.equal((await owner('POST', '/api/users', { local, domain: 'acme.com', name, password: 'password123' })).status, 201);
  await login(a, 'ctra@acme.com'); await login(b, 'ctrb@acme.com');
  const c = (await a('POST', '/api/contacts', { name: 'Pat Plumber', email: 'pat@plumb.example', phone: '0123 456', notes: 'Fixed the boiler', birthday: '1980-04-02' })).body;
  const png = Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==', 'base64');
  assert.equal((await a('PUT', `/api/contacts/${c.id}/photo`, png, { raw: true })).status, 200);
  const g = (await a('POST', '/api/contacts/groups', { name: 'Trades', members: [{ name: 'Pat Plumber', email: 'pat@plumb.example' }] })).body;
  assert.equal((await a('DELETE', `/api/contacts/${c.id}`)).body.trash_days, 30);
  assert.ok(!(await a('GET', '/api/contacts')).body.some((x) => x.id === c.id), 'gone from the list');
  const trash = (await a('GET', '/api/contacts/trash')).body;
  assert.equal(trash.days, 30);
  assert.deepEqual(trash.contacts.map((t) => [t.name, t.email, t.has_photo, t.mine]), [['Pat Plumber', 'pat@plumb.example', true, true]]);
  assert.deepEqual((await b('GET', '/api/contacts/trash')).body.contacts, [], 'only yours');
  assert.equal((await b('POST', `/api/contacts/trash/${c.id}/restore`)).status, 404);
  // Put back: the same id, every field, the photo; the group still has them.
  const back = (await a('POST', `/api/contacts/trash/${c.id}/restore`)).body;
  assert.deepEqual([back.id, back.name, back.phone, back.notes, back.birthday], [c.id, 'Pat Plumber', '0123 456', 'Fixed the boiler', '1980-04-02']);
  assert.equal((await a('GET', `/api/contacts/${c.id}/photo`)).status, 200);
  assert.deepEqual((await a('GET', '/api/contacts/trash')).body.contacts, []);
  assert.equal((await a('GET', '/api/contacts/groups')).body.find((x) => x.id === g.id).members.length, 1);
  // Several at once go to the trash too; delete one for good, then empty it.
  const d = (await a('POST', '/api/contacts', { name: 'Dee Decorator' })).body;
  assert.equal((await a('POST', '/api/contacts/batch', { ids: [c.id, d.id], action: 'delete' })).body.deleted, 2);
  assert.equal((await a('GET', '/api/contacts/trash')).body.contacts.length, 2);
  assert.equal((await a('DELETE', `/api/contacts/trash/${d.id}`)).status, 200);
  assert.deepEqual((await a('GET', '/api/contacts/trash')).body.contacts.map((t) => t.name), ['Pat Plumber']);
  // Older than 30 days: gone by itself.
  const { q } = await import('../src/db.js');
  q('UPDATE contacts_trash SET deleted_at = ? WHERE id = ?').run(Date.now() - 31 * 86400000, c.id);
  assert.deepEqual((await a('GET', '/api/contacts/trash')).body.contacts, []);
  assert.equal((await a('POST', `/api/contacts/trash/${c.id}/restore`)).status, 404);
  assert.equal((await a('DELETE', '/api/contacts/trash')).body.deleted, 0);
});

test('calendar: events shown as free don’t block time; private events are only "Busy" to people who just look', async () => {
  const a = client(), b = client(), c = client();
  const ids = {};
  for (const [local, name] of [['frpa', 'Frp Ann'], ['frpb', 'Frp Ben'], ['frpc', 'Frp Cat']]) ids[local] = (await owner('POST', '/api/users', { local, domain: 'acme.com', name, password: 'password123' })).body.id;
  await login(a, 'frpa@acme.com'); await login(b, 'frpb@acme.com'); await login(c, 'frpc@acme.com');
  const t = Date.UTC(2026, 11, 15, 9);
  const free = (await a('POST', '/api/events', { title: 'Read the news', start: t, end: t + 3600e3, show_as: 'free' })).body;
  const priv = (await a('POST', '/api/events', { title: 'Doctor', location: 'Clinic', description: 'Bring results', start: t + 2 * 3600e3, end: t + 3 * 3600e3, private: true })).body;
  assert.deepEqual([free.show_as, priv.private], ['free', 1]);
  assert.equal((await a('POST', '/api/events', { title: 'x', start: t, end: t + 1, show_as: 'maybe' })).status, 400);
  // Ben sees Ann's details (Share my calendar); Cat only her busy times.
  await a('PUT', '/api/freebusy/shares', { users: [ids.frpb] });
  const fb = async (cl) => (await cl('GET', `/api/freebusy?users=${ids.frpa}&from=${t - 3600e3}&to=${t + 5 * 3600e3}`)).body[ids.frpa].busy;
  const forBen = await fb(b);
  assert.equal(forBen.length, 1, 'the free one doesn’t count as busy');
  assert.deepEqual([forBen[0].start, forBen[0].title, forBen[0].location, forBen[0].private], [t + 2 * 3600e3, 'Busy', undefined, true]);
  assert.deepEqual((await fb(c)).map((x) => [x.start, x.title]), [[t + 2 * 3600e3, undefined]]);
  // A calendar of hers shared to look at: the private event there is "Busy", with nothing else; one who may change it sees it all.
  const team = (await a('POST', '/api/events/calendars', { name: 'Team', color: '#0b8043' })).body;
  const inTeam = (await a('POST', '/api/events', { title: 'Interview: J. Smith', location: 'Room 2', start: t, end: t + 3600e3, calendar_id: team.id, private: true })).body;
  await a('PUT', `/api/events/calendars/${team.id}/members`, { members: [{ id: ids.frpb }, { id: ids.frpc, can_edit: true }] });
  const seen = async (cl) => (await cl('GET', `/api/events?from=${t - 3600e3}&to=${t + 5 * 3600e3}`)).body.find((e) => e.id === inTeam.id);
  const ben = await seen(b);
  assert.deepEqual([ben.title, ben.location, ben.description, ben.masked], ['Busy', null, null, true]);
  assert.equal((await seen(c)).title, 'Interview: J. Smith', 'an editor sees what it is');
  assert.equal((await b('GET', `/api/events/${inTeam.id}/ics`)).status, 404, 'no file that would say what it is');
  assert.equal((await c('GET', `/api/events/${inTeam.id}/ics`)).status, 200);
  // Calendar files say it: TRANSP and CLASS, and reading one keeps them.
  const own = await a('GET', `/api/events/${priv.id}/ics`);
  assert.match(own.body, /CLASS:PRIVATE/);
  assert.match((await a('GET', `/api/events/${free.id}/ics`)).body, /TRANSP:TRANSPARENT/);
  const { parseIcsEvent } = await import('../src/ics.js');
  const parsed = parseIcsEvent('BEGIN:VCALENDAR\r\nBEGIN:VEVENT\r\nUID:x\r\nDTSTART:20261215T090000Z\r\nDTEND:20261215T100000Z\r\nSUMMARY:Gym\r\nTRANSP:TRANSPARENT\r\nCLASS:PRIVATE\r\nEND:VEVENT\r\nEND:VCALENDAR');
  assert.deepEqual([parsed.show_as, parsed.private], ['free', 1]);
  // Back to busy and public.
  const changed = (await a('PATCH', `/api/events/${free.id}`, { show_as: 'busy', private: false })).body;
  assert.deepEqual([changed.show_as, changed.private], [null, 0]);
  assert.equal((await fb(c)).length, 3, 'now busy too (with the doctor and the interview)');
});

