test('contacts: keep in touch — how often, who is due, and writing to them counts', async () => {
  const a = client(), b = client();
  for (const [local, name] of [['kita', 'Kit Ann'], ['kitb', 'Kit Ben']]) assert.equal((await owner('POST', '/api/users', { local, domain: 'acme.com', name, password: 'password123' })).status, 201);
  const ann = await login(a, 'kita@acme.com'); await login(b, 'kitb@acme.com');
  const rita = (await a('POST', '/api/contacts', { name: 'Rita Moreno', email: 'Rita@moreno.example' })).body;
  const bo = (await a('POST', '/api/contacts', { name: 'Bo Chan', email: 'bo@chan.example' })).body;
  await a('POST', '/api/contacts', { name: 'No Reminder' });
  assert.deepEqual((await a('GET', '/api/contacts/keep-in-touch')).body, []);
  assert.equal((await a('PATCH', `/api/contacts/${rita.id}`, { touch_days: 30 })).body.touch_days, 30);
  await a('PATCH', `/api/contacts/${bo.id}`, { touch_days: 7 });
  assert.equal((await a('PATCH', `/api/contacts/${bo.id}`, { touch_days: 3 })).status, 400);
  assert.equal((await b('PATCH', `/api/contacts/${bo.id}`, { touch_days: 7 })).status, 404);
  // Never in touch: both due now.
  assert.deepEqual((await a('GET', '/api/contacts/keep-in-touch')).body.map((c) => c.name).sort(), ['Bo Chan', 'Rita Moreno']);
  // Marked as contacted: Bo isn't due for a week.
  const marked = (await a('POST', `/api/contacts/${bo.id}/contacted`, {})).body;
  assert.ok(Date.now() - marked.last_contact < 5000);
  assert.deepEqual((await a('GET', '/api/contacts/keep-in-touch')).body.map((c) => c.name), ['Rita Moreno']);
  // Sending Rita email counts (whatever the capitals).
  const { recordSent } = await import('../src/othercontacts.js');
  recordSent({ id: ann.id, username: 'kita@acme.com', org_id: (await a('GET', '/api/auth/me')).body.user.org_id }, [{ address: 'rita@MORENO.example', name: 'Rita' }]);
  assert.deepEqual((await a('GET', '/api/contacts/keep-in-touch')).body, []);
  // Long ago: due again.
  const { q } = await import('../src/db.js');
  q('UPDATE contacts SET last_contact = ? WHERE id = ?').run(Date.now() - 31 * 864e5, rita.id);
  const due = (await a('GET', '/api/contacts/keep-in-touch')).body;
  assert.deepEqual(due.map((c) => c.name), ['Rita Moreno']);
  // The bell: once, for those you've been in touch with before (Bo is fine; never-contacted ones don't ping).
  const { notifyDueTouches } = await import('../src/routes/contacts.js');
  const never = (await a('POST', '/api/contacts', { name: 'Never Met' })).body;
  await a('PATCH', `/api/contacts/${never.id}`, { touch_days: 7 });
  notifyDueTouches();
  const bells = async () => (await a('GET', '/api/notifications')).body.items.filter((n) => n.kind === 'touch');
  assert.deepEqual((await bells()).map((n) => [n.title, n.link]), [['Time to catch up with Rita Moreno', '/contacts?tab=touch']]);
  notifyDueTouches();
  assert.equal((await bells()).length, 1, 'not again for the same time');
  await a('POST', `/api/contacts/${rita.id}/contacted`, {});
  q('UPDATE contacts SET last_contact = ? WHERE id = ?').run(Date.now() - 31 * 864e5, rita.id);
  notifyDueTouches();
  assert.equal((await bells()).length, 2, 'due again later: told again');
  await a('PATCH', `/api/contacts/${never.id}`, { touch_days: null });
  await a('PATCH', `/api/contacts/${rita.id}`, { touch_days: null });
  assert.deepEqual((await a('GET', '/api/contacts/keep-in-touch')).body, []);
  assert.equal((await b('POST', `/api/contacts/${rita.id}/contacted`, {})).status, 404);
});

test('calendar: undo deleting an event of your own (not one with guests)', async () => {
  const a = client(), b = client();
  for (const [local, name] of [['ceua', 'Ceu Ann'], ['ceub', 'Ceu Ben']]) assert.equal((await owner('POST', '/api/users', { local, domain: 'acme.com', name, password: 'password123' })).status, 201);
  await login(a, 'ceua@acme.com'); await login(b, 'ceub@acme.com');
  const start = Date.UTC(2026, 11, 3, 9);
  const ev = (await a('POST', '/api/events', { title: 'Dentist', location: 'High St', start, end: start + 36e5, reminders: [30] })).body;
  const del = await a('DELETE', `/api/events/${ev.id}`);
  assert.deepEqual(del.body, { ok: true, undo: true });
  const listed = async () => (await a('GET', `/api/events?from=${start - 864e5}&to=${start + 864e5}`)).body.filter((e) => e.id === ev.id);
  assert.equal((await listed()).length, 0);
  assert.equal((await b('POST', `/api/events/trash/${ev.id}/restore`)).status, 404, 'not Ben’s');
  assert.deepEqual((await a('POST', `/api/events/trash/${ev.id}/restore`)).body, { ok: true, id: ev.id });
  const back = await listed();
  assert.deepEqual([back[0].title, back[0].location, back[0].start], ['Dentist', 'High St', start]);
  assert.deepEqual(back[0].reminders, [30], 'reminders too');
  assert.equal((await a('POST', `/api/events/trash/${ev.id}/restore`)).status, 404, 'once');
  // With a guest: cancelled for them, no undo.
  const withGuest = (await a('POST', '/api/events', { title: 'Meeting', start, end: start + 36e5, guests: ['ceub@acme.com'] })).body;
  assert.deepEqual((await a('DELETE', `/api/events/${withGuest.id}`)).body, { ok: true, undo: false });
  assert.equal((await a('POST', `/api/events/trash/${withGuest.id}/restore`)).status, 404);
});

