test('forms quizzes: answer feedback, shown after submitting (never before), for right or wrong', async () => {
  const { cleanQuestions, scoreOf } = await import('../src/routes/forms.js');
  const qs = cleanQuestions([
    { id: 'cap', type: 'short', title: 'Capital of France?', answer: 'Paris', points: 1, feedback: { right: ' Since 987. ', wrong: 'Have another look at chapter 2.' } },
    { id: 'pick', type: 'choice', title: 'Pick B', options: ['A', 'B'], answer: 'B', feedback: { right: '', wrong: '' } },
    { id: 'free', type: 'paragraph', title: 'Anything?', feedback: { right: 'x' } },
  ]);
  assert.deepEqual(qs[0].feedback, { right: 'Since 987.', wrong: 'Have another look at chapter 2.' });
  assert.equal(qs[1].feedback, undefined, 'empty: none');
  assert.equal(qs[2].feedback, undefined, 'only on marked questions');
  assert.deepEqual(scoreOf(qs, { cap: 'paris', pick: 'A' }).feedback, { cap: 'Since 987.' });
  assert.deepEqual(scoreOf(qs, { cap: 'Lyon', pick: 'B' }).feedback, { cap: 'Have another look at chapter 2.' });
  const a = client(), b = client();
  for (const [local, name] of [['qfa', 'Qf Ann'], ['qfb', 'Qf Ben']]) assert.equal((await owner('POST', '/api/users', { local, domain: 'acme.com', name, password: 'password123' })).status, 201);
  await login(a, 'qfa@acme.com'); await login(b, 'qfb@acme.com');
  const made = (await a('POST', '/api/forms', { title: 'Geography quiz' })).body;
  const f = (await a('PUT', `/api/forms/${made.id}`, { quiz: true, show_score: true, questions: [
    { id: 'cap', type: 'short', title: 'Capital of France?', answer: 'Paris', feedback: { right: 'Since 987.', wrong: 'It’s Paris.' } }] })).body;
  assert.equal(f.questions[0].feedback.wrong, 'It’s Paris.', 'kept for the owner');
  const seen = (await b('GET', `/api/public/forms/${f.token}`)).body;
  assert.equal(seen.questions[0].feedback, undefined, 'not sent before answering');
  assert.equal(seen.questions[0].answer, undefined);
  const sent = (await b('POST', `/api/public/forms/${f.token}`, { answers: { cap: 'Lyon' } })).body;
  assert.deepEqual([sent.score, sent.feedback], [0, { cap: 'It’s Paris.' }]);
  // Without "show people their score", no feedback either.
  await a('PUT', `/api/forms/${made.id}`, { show_score: false });
  const quiet = (await b('POST', `/api/public/forms/${f.token}`, { answers: { cap: 'Paris' } })).body;
  assert.equal(quiet.feedback, undefined);
});

test('forms: the emailed copy of a quiz response has each question’s mark and feedback', async () => {
  const { copyText, scoreOf, cleanQuestions } = await import('../src/routes/forms.js');
  const questions = cleanQuestions([{ id: 'cap', type: 'short', title: 'Capital of France?', answer: 'Paris', feedback: { wrong: 'It’s Paris.' } },
    { id: 'n', type: 'short', title: 'Your name' }]);
  const answers = { cap: 'Lyon', n: 'Ann' };
  const text = copyText({ title: 'Quiz', questions }, answers, scoreOf(questions, answers), 'https://ws/f/x?edit=k');
  assert.match(text, /Your score: 0 \/ 1\n✗ Capital of France\? — It’s Paris\./);
  assert.match(text, /To change your answers: https:\/\/ws\/f\/x\?edit=k$/);
  assert.doesNotMatch(copyText({ title: 'Quiz', questions }, answers, null, null), /score|✗/, 'no score shown: no marks');
});

test('tasks: schedule time for a task on your calendar, with a link back and a warning about clashes', async () => {
  const a = client(), c = client();
  for (const [local, name] of [['tba', 'Tb Ann'], ['tbc', 'Tb Cat']]) assert.equal((await owner('POST', '/api/users', { local, domain: 'acme.com', name, password: 'password123' })).status, 201);
  await login(a, 'tba@acme.com'); await login(c, 'tbc@acme.com');
  const list = (await a('POST', '/api/tasks/lists', { name: 'Tb list' })).body.id;
  const t = (await a('POST', `/api/tasks/lists/${list}/tasks`, { title: 'Write the report' })).body;
  const at = Date.now() + 2 * 864e5 - (Date.now() % 36e5);
  await a('POST', '/api/events', { title: 'Team meeting', start: at + 30 * 60e3, end: at + 90 * 60e3 });
  await a('POST', '/api/events', { title: 'Lunch (free)', start: at, end: at + 36e5, show_as: 'free' });
  // Checking first: the meeting clashes, the free one doesn't.
  const check = (await a('GET', `/api/tasks/tasks/${t.id}/blocks?start=${at}&end=${at + 36e5}`)).body;
  assert.deepEqual(check.clashes.map((x) => x.title), ['Team meeting']);
  assert.deepEqual(check.blocks, []);
  const made = await a('POST', `/api/tasks/tasks/${t.id}/blocks`, { start: at, end: at + 36e5, tz: 'Europe/London' });
  assert.equal(made.status, 201);
  assert.equal(made.body.event.title, '✓ Write the report');
  assert.deepEqual(made.body.clashes.map((x) => x.title), ['Team meeting'], 'booked anyway, with a warning');
  const ev = (await a('GET', `/api/events?from=${at - 1}&to=${at + 36e5 + 1}`)).body.find((e) => e.id === made.body.event.id);
  assert.equal(ev.task_id, t.id);
  assert.deepEqual(ev.task, { id: t.id, list_id: list, title: 'Write the report', done: false }, 'the event knows its task, for Open task');
  assert.match(ev.description, new RegExp(`/tasks/${list}\\?task=${t.id}`));
  assert.deepEqual((await a('GET', `/api/tasks/tasks/${t.id}/blocks`)).body.blocks.map((b) => b.start), [at]);
  // Its own block isn't a clash for another one right after.
  assert.deepEqual((await a('GET', `/api/tasks/tasks/${t.id}/blocks?start=${at}&end=${at + 36e5}`)).body.clashes.map((x) => x.title), ['Team meeting']);
  // Checks.
  assert.equal((await a('POST', `/api/tasks/tasks/${t.id}/blocks`, { start: at, end: at })).status, 400);
  assert.equal((await a('POST', `/api/tasks/tasks/${t.id}/blocks`, { start: at, end: at + 9 * 36e5 })).status, 400, 'at most 8 hours');
  assert.equal((await c('POST', `/api/tasks/tasks/${t.id}/blocks`, { start: at, end: at + 36e5 })).status, 404, 'only people on the list');
});

test('chat: send a company contact (view only) or a colleague’s card', async () => {
  const a = client(), b = client();
  for (const [local, name] of [['scda', 'Scd Ann'], ['scdb', 'Scd Ben']]) assert.equal((await owner('POST', '/api/users', { local, domain: 'acme.com', name, password: 'password123' })).status, 201);
  const aid = (await login(a, 'scda@acme.com')).id;
  const bid = (await login(b, 'scdb@acme.com')).id;
  await a('PUT', '/api/users/me/profile', { job_title: 'Buyer', department: 'Purchasing', work_phone: '+60 3 5555' });
  const shared = (await a('POST', '/api/contacts', { name: 'Supplier Sue', email: 'sue@supply.example', shared: true })).body;
  const dm = (await b('POST', '/api/chat/dm', { user_id: aid })).body.id;
  // Ben can only view the company contact, but can pass it on.
  const m1 = await b('POST', `/api/chat/channels/${dm}/contact`, { contact_id: shared.id });
  assert.equal(m1.status, 201); assert.equal(m1.body.contact.name, 'Supplier Sue');
  // A colleague's card: their name, address, job title and work phone.
  const m2 = (await a('POST', `/api/chat/channels/${dm}/contact`, { user_id: bid })).body;
  assert.deepEqual({ name: m2.contact.name, email: m2.contact.email }, { name: 'Scd Ben', email: 'scdb@acme.com' });
  const m3 = (await b('POST', `/api/chat/channels/${dm}/contact`, { user_id: aid })).body;
  assert.equal(m3.contact.title, 'Buyer'); assert.equal(m3.contact.phone, '+60 3 5555'); assert.match(m3.contact.company, /Purchasing/);
  // Someone at another company: no.
  assert.equal((await a('POST', `/api/chat/channels/${dm}/contact`, { user_id: ginaId })).status, 404);
  // Saved into Ben's contacts like any other.
  assert.equal((await b('POST', `/api/chat/messages/${m3.id}/contact/save`)).body.existing, false);
  assert.ok((await b('GET', '/api/contacts')).body.some((c) => c.email === 'scda@acme.com' && c.title === 'Buyer'));
});

test('comments: emoji reactions, one of each per person, for anyone who can comment', async () => {
  const a = client(), b = client(), v = client();
  for (const [local, name] of [['cra', 'Cr Ann'], ['crb', 'Cr Ben'], ['crv', 'Cr Vic']]) assert.equal((await owner('POST', '/api/users', { local, domain: 'acme.com', name, password: 'password123' })).status, 201);
  await login(a, 'cra@acme.com');
  const bid = (await login(b, 'crb@acme.com')).id;
  const vid = (await login(v, 'crv@acme.com')).id;
  const doc = (await a('POST', '/api/files/new', { kind: 'doc', name: 'Cr plan' })).body;
  await a('PUT', `/api/files/${doc.id}/shares`, { shares: [{ user_id: bid, role: 'commenter' }, { user_id: vid, role: 'viewer' }] });
  const c = (await a('POST', `/api/comments/${doc.id}`, { body: 'Shall we ship Friday?', anchor: { quote: 'ship' }, id: 'cr-thread-1' })).body.comment;
  let r = (await b('POST', `/api/comments/${doc.id}/${c.id}/reactions`, { emoji: '👍' })).body;
  assert.deepEqual(r.reactions, [{ emoji: '👍', users: [{ id: bid, name: 'Cr Ben' }] }]);
  r = (await a('POST', `/api/comments/${doc.id}/${c.id}/reactions`, { emoji: '👍' })).body;
  r = (await a('POST', `/api/comments/${doc.id}/${c.id}/reactions`, { emoji: '🎉' })).body;
  assert.deepEqual(r.reactions.map((x) => [x.emoji, x.users.map((u) => u.name)]), [['👍', ['Cr Ben', 'Cr Ann']], ['🎉', ['Cr Ann']]]);
  // The same again takes it back.
  r = (await b('POST', `/api/comments/${doc.id}/${c.id}/reactions`, { emoji: '👍' })).body;
  assert.deepEqual(r.reactions[0].users.map((u) => u.name), ['Cr Ann']);
  // In the list everyone reads; viewers can't react; only emoji.
  assert.equal((await v('GET', `/api/comments/${doc.id}`)).body[0].reactions.length, 2);
  assert.equal((await v('POST', `/api/comments/${doc.id}/${c.id}/reactions`, { emoji: '👍' })).status, 403);
  assert.equal((await b('POST', `/api/comments/${doc.id}/${c.id}/reactions`, { emoji: 'lol' })).status, 400);
  assert.equal((await b('POST', `/api/comments/${doc.id}/nope/reactions`, { emoji: '👍' })).status, 404);
  // Deleting the comment takes its reactions too.
  await a('DELETE', `/api/comments/${doc.id}/${c.id}`);
  assert.deepEqual((await a('GET', `/api/comments/${doc.id}`)).body, []);
});

test('notes: show and hide tick boxes (text ⇄ checklist), kept in the version history', async () => {
  const { textToItems, itemsToText } = await import('../src/routes/notes.js');
  const items = textToItems('Packing\n- Passport\n  * Visa copy\n[x] Tickets\n✓ Charger\n\n1. Snacks');
  assert.deepEqual(items.map(({ id, ...i }) => i), [
    { text: 'Packing', done: false }, { text: 'Passport', done: false }, { text: 'Visa copy', done: false, indent: 1 },
    { text: 'Tickets', done: true }, { text: 'Charger', done: true }, { text: 'Snacks', done: false }]);
  assert.equal(itemsToText(items), 'Packing\nPassport\n  Visa copy\n✓ Tickets\n✓ Charger\nSnacks');
  assert.deepEqual(textToItems(itemsToText(items)).map(({ id, ...i }) => i), items.map(({ id, ...i }) => i), 'and back');
  assert.equal(textToItems('  starts indented')[0].indent, undefined, 'the first can’t be a sub-item');
  const a = client();
  assert.equal((await owner('POST', '/api/users', { local: 'ncva', domain: 'acme.com', name: 'Ncv Ann', password: 'password123' })).status, 201);
  await login(a, 'ncva@acme.com');
  const n = (await a('POST', '/api/notes', { title: 'Trip', body: 'Passport\nTickets' })).body;
  const c = (await a('POST', `/api/notes/${n.id}/convert`, { to: 'checklist' })).body;
  assert.deepEqual([c.body, c.items.map((i) => i.text)], ['', ['Passport', 'Tickets']]);
  assert.equal((await a('POST', `/api/notes/${n.id}/convert`, { to: 'checklist' })).status, 400, 'already');
  await a('PATCH', `/api/notes/${n.id}`, { items: c.items.map((i, k) => ({ ...i, done: k === 1 })) });
  const t = (await a('POST', `/api/notes/${n.id}/convert`, { to: 'text' })).body;
  assert.deepEqual([t.items, t.body], [null, 'Passport\n✓ Tickets']);
  assert.ok((await a('GET', `/api/notes/${n.id}/versions`)).body.length >= 1, 'the earlier one kept');
  assert.equal((await a('POST', `/api/notes/${n.id}/convert`, { to: 'other' })).status, 400);
});

