test('a folder’s activity covers what happens inside it, saying which item; a file’s is its own', async () => {
  const a = client(), b = client();
  for (const [local, name] of [['fata', 'Act Ann'], ['fatb', 'Act Ben']]) assert.equal((await owner('POST', '/api/users', { local, domain: 'acme.com', name, password: 'password123' })).status, 201);
  await login(a, 'fata@acme.com');
  const bid = (await login(b, 'fatb@acme.com')).id;
  const top = (await a('POST', '/api/files/folder', { name: 'Act top' })).body.id;
  const sub = (await a('POST', '/api/files/folder', { name: 'Act sub', parent_id: top })).body.id;
  const doc = (await a('POST', '/api/files/new', { kind: 'doc', name: 'Act doc', parent_id: sub })).body.id;
  await a('PUT', `/api/files/${top}/shares`, { shares: [{ user_id: bid, role: 'editor' }] });
  await b('PATCH', `/api/files/${doc}`, { name: 'Act doc v2' });
  await b('PATCH', `/api/files/${doc}`, { trashed: true });
  const acts = (await b('GET', `/api/files/${top}/activity`)).body;
  assert.equal(acts[0].action, 'trash');
  assert.equal(acts[0].user_name, 'Act Ben');
  assert.deepEqual(acts[0].file, { id: doc, name: 'Act doc v2', kind: 'doc' }, 'which item, as it’s called now');
  assert.ok(acts.some((x) => x.action === 'rename' && x.file?.id === doc));
  assert.ok(acts.some((x) => x.action === 'create' && x.file?.id === sub));
  const own = acts.filter((x) => !x.file);
  assert.ok(own.some((x) => x.action === 'share'), 'the folder’s own entries have no file');
  // The sub-folder's covers only what's under it; a file's is its own, without a file field.
  assert.ok((await b('GET', `/api/files/${sub}/activity`)).body.every((x) => !x.file || x.file.id === doc));
  const docActs = (await b('GET', `/api/files/${doc}/activity`)).body;
  assert.ok(docActs.length >= 2 && docActs.every((x) => !('file' in x)));
});

test('activity comes 100 at a time, newest first; ?before= gives the older ones', async () => {
  const a = client();
  assert.equal((await owner('POST', '/api/users', { local: 'fapg', domain: 'acme.com', name: 'Page Ann', password: 'password123' })).status, 201);
  await login(a, 'fapg@acme.com');
  const folder = (await a('POST', '/api/files/folder', { name: 'Busy folder' })).body.id;
  const d = (await a('POST', '/api/files/new', { kind: 'doc', name: 'n0', parent_id: folder })).body.id;
  for (let i = 1; i <= 120; i++) await a('PATCH', `/api/files/${d}`, { name: `n${i}` });
  const first = (await a('GET', `/api/files/${folder}/activity`)).body;
  assert.equal(first.length, 100);
  assert.equal(first[0].details.to, 'n120');
  assert.ok(first.every((x, i) => i === 0 || x.id < first[i - 1].id), 'newest first, with ids');
  const older = (await a('GET', `/api/files/${folder}/activity?before=${first.at(-1).id}`)).body;
  assert.equal(older.length, 120 + 2 - 100, 'the rest: renames, the doc made, the folder made');
  assert.ok(older.every((x) => x.id < first.at(-1).id));
  assert.equal(older.at(-1).action, 'create');
  assert.equal(older.at(-1).file, undefined, 'the folder itself');
  // A file pages the same way.
  const fileFirst = (await a('GET', `/api/files/${d}/activity`)).body;
  assert.equal(fileFirst.length, 100);
  assert.equal((await a('GET', `/api/files/${d}/activity?before=${fileFirst.at(-1).id}`)).body.length, 21);
  assert.equal((await a('GET', `/api/files/${d}/activity?before=nonsense`)).body.length, 100, 'ignored');
});

test('Drive → Activity: what others did lately to files you can open, not your own doings, not what you can’t open', async () => {
  const a = client(), b = client(), c = client();
  for (const [local, name] of [['rcta', 'Rec Ann'], ['rctb', 'Rec Ben'], ['rctc', 'Rec Cy']]) assert.equal((await owner('POST', '/api/users', { local, domain: 'acme.com', name, password: 'password123' })).status, 201);
  const aid = (await login(a, 'rcta@acme.com')).id;
  await login(b, 'rctb@acme.com');
  await login(c, 'rctc@acme.com');
  const shared = (await b('POST', '/api/files/folder', { name: 'Rec shared' })).body.id;
  await b('PUT', `/api/files/${shared}/shares`, { shares: [{ user_id: aid, role: 'editor' }] });
  const inside = (await b('POST', '/api/files/new', { kind: 'doc', name: 'Rec inside', parent_id: shared })).body.id;
  await b('PATCH', `/api/files/${inside}`, { name: 'Rec inside 2' });
  await c('POST', '/api/files/new', { kind: 'doc', name: 'Rec secret' });
  const mine = (await a('POST', '/api/files/new', { kind: 'doc', name: 'Rec mine' })).body.id;
  await a('PATCH', `/api/files/${mine}`, { name: 'Rec mine 2' });

  const feed = (await a('GET', '/api/files/activity/recent')).body;
  const names = feed.map((x) => `${x.user_name}:${x.action}:${x.file.name}`);
  assert.equal(names[0], 'Rec Ben:rename:Rec inside 2', 'newest first');
  assert.ok(names.includes('Rec Ben:create:Rec inside 2'));
  assert.ok(names.includes('Rec Ben:share:Rec shared'));
  assert.ok(!names.some((n) => n.includes('Rec secret')), 'not what she can’t open');
  assert.ok(!names.some((n) => n.startsWith('Rec Ann:')), 'not her own doings');
  assert.equal(feed[0].file.kind, 'doc');
  // Paging, and the trash.
  assert.deepEqual((await a('GET', `/api/files/activity/recent?before=${feed[0].id}`)).body.map((x) => x.id), feed.slice(1).map((x) => x.id));
  await b('PATCH', `/api/files/${inside}`, { trashed: true });
  assert.ok(!(await a('GET', '/api/files/activity/recent')).body.some((x) => x.file.id === inside), 'trashed files drop out');
});

