  const zip = await JSZip.loadAsync((await a('GET', '/api/takeout', undefined, { binary: true })).body);
  const csv = await zip.file('Comments.csv').async('string');
  const lines = csv.replace(/^\ufeff/, '').trim().split('\r\n');
