test('notes: import from Google Keep (Takeout .json): text and checklists, colour, pin, archive, labels, dates; trashed and empty skipped', async () => {
  const a = client();
  assert.equal((await owner('POST', '/api/users', { local: 'keepa', domain: 'acme.com', name: 'Keep Ann', password: 'password123' })).status, 201);
  await login(a, 'keepa@acme.com');
  const keep = [
    { title: 'Groceries', listContent: [{ text: 'Milk', isChecked: false }, { text: 'Bread', isChecked: true }], color: 'YELLOW', isPinned: true, labels: [{ name: 'Home' }], createdTimestampUsec: 1700000000000000, userEditedTimestampUsec: 1700000500000000 },
    { title: 'Old idea', textContent: 'Kites for the office', color: 'DEFAULT', isArchived: true },
    { title: 'Binned', textContent: 'gone', isTrashed: true },
    { title: '', textContent: '   ' },
  ];
  const r = await a('POST', '/api/notes/import', { files: [...keep.map((k, i) => ({ name: `note${i}.json`, text: JSON.stringify(k) })), { name: 'plain.md', text: '# From Markdown\nStill works' }] });
  assert.equal(r.status, 201, JSON.stringify(r.body));
  assert.deepEqual(r.body, { added: 3, skipped: 2 });
  const live = (await a('GET', '/api/notes')).body;
  const g = live.find((n) => n.title === 'Groceries');
  assert.deepEqual(g.items.map((i) => [i.text, i.done]), [['Milk', false], ['Bread', true]]);
  assert.equal(g.color, '#fff8b8');
  assert.equal(g.pinned, true);
  assert.deepEqual(g.labels, ['Home']);
  assert.equal(g.created_at, 1700000000000);
  assert.equal(g.updated_at, 1700000500000);
  assert.ok(!live.some((n) => n.title === 'Old idea'), 'archived ones go to the archive');
  const arch = (await a('GET', '/api/notes?archived=1')).body.find((n) => n.title === 'Old idea');
  assert.equal(arch.body, 'Kites for the office');
  assert.equal(arch.color, null);
  assert.ok(live.some((n) => n.title === 'From Markdown'), 'Markdown files alongside');
  assert.equal((await a('POST', '/api/notes/import', { files: [{ name: 'bad.json', text: '{nope' }] })).status, 400);
});

test('tasks: import from Google Tasks (Takeout Tasks.json): lists, order, notes, due dates, done ones, subtasks as steps', async () => {
  const { listsFromGoogleTasks } = await import('../src/googletasks.js');
  const data = { kind: 'tasks#taskLists', items: [
    { kind: 'tasks#taskList', title: 'Errands', items: [
      { id: 'b', title: 'Post office', position: '00000000000000000001', status: 'needsAction', due: '2026-12-01T00:00:00.000Z' },
      { id: 'a', title: 'Buy paint', position: '00000000000000000000', status: 'needsAction', notes: 'White, matt' },
      { id: 'a1', title: 'Brushes', parent: 'a', position: '00000000000000000000', status: 'completed' },
      { id: 'a2', title: 'Tape', parent: 'a', position: '00000000000000000001', status: 'needsAction' },
      { id: 'c', title: 'Return books', status: 'completed', completed: '2026-10-05T10:00:00.000Z', position: '00000000000000000002' },
      { id: 'd', title: 'Gone', deleted: true },
    ] },
    { kind: 'tasks#taskList', title: 'Empty list', items: [] },
  ] };
  const found = listsFromGoogleTasks(data);
  assert.deepEqual(found.lists[0].tasks.map((t) => t.title), ['Buy paint', 'Post office', 'Return books'], 'in their order; deleted left out');
  assert.deepEqual(found.lists[0].tasks[0].steps, [{ title: 'Brushes', done: true }, { title: 'Tape', done: false }]);
  assert.equal(found.lists[0].tasks[1].due, '2026-12-01');
  assert.equal(found.lists[0].tasks[2].done_at, Date.parse('2026-10-05T10:00:00.000Z'));
  assert.ok(listsFromGoogleTasks({ hello: 1 }).error);

  const a = client();
  assert.equal((await owner('POST', '/api/users', { local: 'gtsk', domain: 'acme.com', name: 'Gt Ann', password: 'password123' })).status, 201);
  await login(a, 'gtsk@acme.com');
  const r = await a('POST', '/api/tasks/import/google', { data });
  assert.equal(r.status, 201, JSON.stringify(r.body));
  assert.deepEqual(r.body.lists.map((l) => [l.name, l.tasks]), [['Errands', 3]], 'empty lists aren’t made');
  const tasks = (await a('GET', `/api/tasks/lists/${r.body.lists[0].id}/tasks`)).body;
  const list = Array.isArray(tasks) ? tasks : tasks.tasks;
  const paint = list.find((t) => t.title === 'Buy paint');
  assert.equal(paint.notes, 'White, matt');
  assert.deepEqual(paint.steps.map((s) => [s.title, s.done]), [['Brushes', true], ['Tape', false]]);
  assert.ok(list.find((t) => t.title === 'Return books').done);
  assert.equal((await a('POST', '/api/tasks/import/google', { data: { items: [] } })).status, 400);
  assert.equal((await a('POST', '/api/tasks/import/google', { data: 'nope' })).status, 400);
});

test('chat: admins import a Slack export: channels, messages with their dates, threads, people matched by email', async () => {
  const JSZip = (await import('jszip')).default;
  const { slackText } = await import('../src/slackimport.js');
  const { q: q0 } = await import('../src/db.js');
  assert.equal(slackText('Hi <@U1> see <#C2|launch>, <https://x.com|the plan> &amp; <!channel>', new Map([['U1', { name: 'Sia Lee' }]])), 'Hi @Sia Lee see #launch, the plan (https://x.com) & @channel');
  const s = client();
  const sid = (await owner('POST', '/api/users', { local: 'sialee', domain: 'acme.com', name: 'Sia Lee', password: 'password123' })).body.id;
  await login(s, 'sialee@acme.com');
  const zip = new JSZip();
  const root = zip.folder('Acme Slack export');
  root.file('users.json', JSON.stringify([{ id: 'U1', profile: { real_name: 'Sia Lee', email: 'SiaLee@acme.com' } }, { id: 'U2', profile: { real_name: 'Old Contractor', email: 'old@elsewhere.com' } }]));
  root.file('channels.json', JSON.stringify([{ name: 'slack-launch', topic: { value: 'Launch plans' } }, { name: 'slack-old', is_archived: true }]));
  root.file('slack-launch/2024-03-01.json', JSON.stringify([
    { type: 'message', user: 'U1', text: 'Kick-off at 10', ts: '1709280000.000100', reactions: [{ name: '+1', users: ['U1', 'U2'] }, { name: 'tada::skin-tone-2', users: ['U1'] }, { name: 'our-custom-logo', users: ['U1'] }] },
    { type: 'message', subtype: 'channel_join', user: 'U2', text: '<@U2> has joined', ts: '1709280001.0' },
    { type: 'message', user: 'U2', text: 'Ready, <@U1>', ts: '1709280060.000200', thread_ts: '1709280000.000100' },
  ]));
  root.file('slack-launch/2024-03-02.json', JSON.stringify([{ type: 'message', user: 'U1', text: 'Day two', ts: '1709366400.0', files: [{ name: 'plan.pdf' }], pinned_to: ['C1'], edited: { ts: '1709366500.0' } }]));
  const body = await zip.generateAsync({ type: 'nodebuffer' });
  assert.equal((await s('POST', '/api/chat/import/slack', body, { raw: true, headers: { 'content-type': 'application/zip' } })).status, 403, 'admins only');
  const pre = await owner('POST', '/api/chat/import/slack?preview=1', body, { raw: true, headers: { 'content-type': 'application/zip' } });
  assert.equal(pre.status, 200, JSON.stringify(pre.body));
  assert.deepEqual(pre.body, { channels: [{ name: 'slack-launch', messages: 3, archived: false, renamed: false }], messages: 3, people_matched: 1, not_here: ['Old Contractor'] });
  assert.equal(q0('SELECT COUNT(*) AS n FROM channels WHERE name = ?').get('slack-launch').n, 0, 'a preview writes nothing');
  const r = await owner('POST', '/api/chat/import/slack', body, { raw: true, headers: { 'content-type': 'application/zip' } });
  assert.equal(r.status, 201, JSON.stringify(r.body));
  assert.deepEqual(r.body.channels.map((c) => [c.name, c.messages]), [['slack-launch', 3]], 'empty archived channels skipped');
  assert.equal(r.body.messages, 3);
  assert.deepEqual([r.body.people_matched, r.body.people_not_here], [1, 1]);
  const ch = r.body.channels[0].id;
  const msgs = (await s('GET', `/api/chat/channels/${ch}/messages`)).body;
  const list = Array.isArray(msgs) ? msgs : msgs.messages;
  const kick = list.find((m) => m.body === 'Kick-off at 10');
  assert.equal(kick.user_id, sid, 'matched by email');
  assert.equal(kick.created_at, 1709280000000);
  assert.ok(list.some((m) => m.body === 'Day two\n📎 plan.pdf'));
  const { q } = await import('../src/db.js');
  const reply = q('SELECT * FROM messages WHERE channel_id = ? AND parent_id IS NOT NULL').get(ch);
  const day2 = q("SELECT * FROM messages WHERE channel_id = ? AND body LIKE 'Day two%'").get(ch);
  assert.ok(day2.pinned_at && day2.edited_at, 'pinned and edited in Slack: here too');
  assert.equal(reply.body, 'Ready, @Sia Lee');
  assert.equal(reply.bot, 'Old Contractor', 'not here: their Slack name');
  assert.equal(reply.parent_id, kick.id, 'a thread reply');
  assert.deepEqual([r.body.reactions, r.body.reactions_left_out], [2, 2], 'Sia’s 👍 and 🎉; the contractor’s 👍 and the custom emoji left out');
  assert.deepEqual(kick.reactions.map((x) => [x.emoji, x.users.map((u) => u.id)]).sort(), [['👍', [sid]], ['🎉', [sid]]].sort());
  const mine = (await s('GET', '/api/chat/channels')).body.channels.find((c) => c.id === ch);
  assert.equal(mine.unread, 0, 'the history isn’t all unread');
  // Again: the name is taken now.
  assert.equal((await owner('POST', '/api/chat/import/slack', body, { raw: true, headers: { 'content-type': 'application/zip' } })).body.channels[0].name, 'slack-launch (Slack)');
  assert.equal((await owner('POST', '/api/chat/import/slack', Buffer.from('not a zip'), { raw: true, headers: { 'content-type': 'application/zip' } })).status, 400);
  // Only some channels: by name; none of them known is refused.
  const two = new JSZip();
  two.file('channels.json', JSON.stringify([{ name: 'pick-a' }, { name: 'pick-b' }]));
  two.file('pick-a/2024-01-01.json', JSON.stringify([{ type: 'message', user: 'U9', text: 'in a', ts: '1704100000.0' }]));
  two.file('pick-b/2024-01-01.json', JSON.stringify([{ type: 'message', user: 'U9', text: 'in b', ts: '1704100000.0' }]));
  const twoBody = await two.generateAsync({ type: 'nodebuffer' });
  const some = await owner('POST', '/api/chat/import/slack?channels=pick-b', twoBody, { raw: true, headers: { 'content-type': 'application/zip' } });
  assert.deepEqual(some.body.channels.map((c) => c.name), ['pick-b']);
  assert.equal((await owner('POST', '/api/chat/import/slack?channels=nope', twoBody, { raw: true, headers: { 'content-type': 'application/zip' } })).status, 400);
});

test('tasks: import a Trello board: its lists as sections, cards as tasks with checklists, labels, due dates', async () => {
  const board = {
    name: 'Website relaunch',
    lists: [{ id: 'L2', name: 'Doing', pos: 2 }, { id: 'L1', name: 'To do', pos: 1 }, { id: 'L3', name: 'Old', pos: 3, closed: true }],
    cards: [
      { name: 'Write copy', desc: 'Home and About pages', idList: 'L1', pos: 2, due: '2026-12-10T12:00:00.000Z', labels: [{ name: 'Content', color: 'green' }], idChecklists: ['C1'] },
      { name: 'Pick fonts', idList: 'L1', pos: 1, labels: [{ name: '', color: 'red' }] },
      { name: 'Set up hosting', idList: 'L2', pos: 1, dueComplete: true },
      { name: 'Archived card', idList: 'L1', pos: 3, closed: true },
      { name: 'In a closed list', idList: 'L3', pos: 1 },
    ],
    checklists: [{ id: 'C1', name: 'Pages', checkItems: [{ name: 'About', state: 'incomplete', pos: 2 }, { name: 'Home', state: 'complete', pos: 1 }] }],
  };
  const a = client();
  assert.equal((await owner('POST', '/api/users', { local: 'trel', domain: 'acme.com', name: 'Tre Ann', password: 'password123' })).status, 201);
  await login(a, 'trel@acme.com');
  const r = await a('POST', '/api/tasks/import/trello', { data: board });
  assert.equal(r.status, 201, JSON.stringify(r.body));
  assert.deepEqual([r.body.name, r.body.sections, r.body.tasks], ['Website relaunch', 2, 3]);
  const got = (await a('GET', `/api/tasks/lists/${r.body.id}/tasks`)).body;
  const tasks = Array.isArray(got) ? got : got.tasks;
  const copy = tasks.find((t) => t.title === 'Write copy');
  assert.equal(copy.notes, 'Home and About pages');
  assert.equal(copy.due, '2026-12-10');
  assert.deepEqual(copy.steps.map((s) => [s.title, s.done]), [['Home', true], ['About', false]]);
  assert.deepEqual(copy.tags, ['content']);
  assert.deepEqual(tasks.find((t) => t.title === 'Pick fonts').tags, ['red'], 'a label with no name: its colour');
  assert.ok(tasks.find((t) => t.title === 'Set up hosting').done);
  assert.ok(!tasks.some((t) => /Archived|closed list/.test(t.title)));
  const { q } = await import('../src/db.js');
  assert.deepEqual(q('SELECT name FROM task_sections WHERE list_id = ? ORDER BY position').all(r.body.id).map((x) => x.name), ['To do', 'Doing']);
  assert.equal(q('SELECT s.name FROM tasks t JOIN task_sections s ON s.id = t.section_id WHERE t.title = ?').get('Pick fonts').name, 'To do');
  assert.equal((await a('POST', '/api/tasks/import/trello', { data: { hello: 1 } })).status, 400);
});

